L["For %s: he still needs %d"] = "Pour %s : il lui en faut encore %d"
L["For %s: still needs %d"] = "Pour %s : il lui en faut encore %d"
L["Party members who run Polestar see your counts under their quest goals, your step and your level. Hidden addon messages to your party only; nothing goes to chat."] = "Les membres du groupe qui utilisent Polestar voient vos compteurs sous leurs objectifs de quête, votre étape et votre niveau. Des messages d'addon cachés, à votre groupe seulement ; rien ne part dans le chat."
L["Their counts under your quest goals, and who lacks a quest you took, with a Share button."] = "Leurs compteurs sous vos objectifs de quête, et qui n'a pas une quête que vous avez prise, avec un bouton Partager."
L["Wait for the group"] = "Attendre le groupe"
L["When a party member on your quest still needs an objective you finished, the step and its turn-in wait and the arrow leads to what they need. Members in another zone or offline for 2 minutes don't hold you; the party line offers Go on without them."] = "Quand un membre du groupe sur votre quête a encore besoin d'un objectif que vous avez fini, l'étape et sa quête à rendre attendent, et la flèche mène à ce qu'il lui faut. Un membre dans une autre zone ou hors ligne depuis 2 minutes ne vous retient pas ; la ligne du groupe propose Continuer sans eux."
L["Say who still needs quest loot"] = "Dire qui a encore besoin du butin de quête"
L["On a loot window or roll, a line under a quest item a party member still needs and you don't. Nothing is passed or said for you."] = "Dans une fenêtre de butin ou un jet, une ligne pour un objet de quête dont un membre du groupe a encore besoin et pas vous. Rien n'est passé ni dit à votre place."
L["Party panel"] = "Panneau du groupe"
L["Opens by itself when someone in your party runs Polestar too: each member's level, step and what they still need of yours; click a name to point the arrow at them. Closed, it stays closed; /polestar party opens it again."] = "S'ouvre tout seul quand quelqu'un de votre groupe utilise aussi Polestar : niveau, étape de chaque membre et ce qu'il lui manque de vos quêtes ; cliquez sur un nom pour y diriger la flèche. Fermé, il reste fermé ; /polestar party le rouvre."
L["Tell my party about objectives and ready quests"] = "Prévenir mon groupe des objectifs et des quêtes prêtes à rendre"
L["A party chat line with the quest's link when you finish its objectives, and one when the quest is ready to turn in. Everyone in the party sees it, Polestar or not. Never solo or in a raid."] = "Une ligne dans le chat de groupe avec le lien de la quête quand vous terminez ses objectifs, et une autre quand la quête est prête à rendre. Tout le groupe la voit, avec ou sans Polestar. Jamais en solo ni en raid."
L["Tell my party when I loot an item that starts a quest"] = "Prévenir mon groupe quand je ramasse un objet qui lance une quête"
L["A party chat line with the item's link and the quest it starts."] = "Une ligne dans le chat de groupe avec le lien de l'objet et la quête qu'il lance."
L["Show my own lines in my chat too"] = "Afficher aussi mes propres lignes dans mon chat"
L["Off: your party sees the lines Polestar says for you, and your chat stays clear of them."] = "Désactivé : votre groupe voit les lignes que Polestar dit pour vous, et votre chat en reste libre."
L["Hide other players' Polestar lines"] = "Masquer les lignes Polestar des autres joueurs"
L["Party members' Polestar lines leave your chat. Shown, they carry Polestar's star."] = "Les lignes Polestar des membres du groupe quittent votre chat. Affichées, elles portent l'étoile de Polestar."
L["Only when someone in the party doesn't have Polestar"] = "Seulement si quelqu'un du groupe n'a pas Polestar"
L["Nothing goes to chat while everyone in your party runs Polestar: they see your progress in their guide."] = "Rien ne part dans le chat tant que tout votre groupe utilise Polestar : ils voient votre progression dans leur guide."
L["%s asks you to sync to their guide."] = "%s vous propose de vous synchroniser sur son guide."
L["You'll switch to %s."] = "Vous passerez à %s."
L["Their step: %s"] = "Son étape : %s"
L["You're past their step: your guide stays where you are."] = "Vous avez dépassé son étape : votre guide reste où vous en êtes."
L["%s is past these, which you haven't done: %s"] = "%s a dépassé celles-ci, que vous n'avez pas faites : %s"
L["You've done these already, so your guide passes them: %s"] = "Vous les avez déjà faites, votre guide les passe donc : %s"
L["%s asked you to sync to their guide, but it isn't for your character or your copy lacks their step."] = "%s vous a proposé de vous synchroniser sur son guide, mais il n'est pas pour votre personnage ou votre copie n'a pas son étape."
L["No room for another guide tab: close one, then ask %s again."] = "Plus de place pour un autre onglet de guide : fermez-en un, puis redemandez à %s."
L["%s synced to your guide."] = "%s s'est synchronisé sur votre guide."
L["%s declined to sync."] = "%s a refusé la synchro."
L["%s can't sync: your guide isn't for their character, or their copy lacks your step."] = "%s ne peut pas se synchroniser : votre guide n'est pas pour son personnage, ou sa copie n'a pas votre étape."
L["%s is already on your step."] = "%s est déjà à votre étape."
L["No one else in your party has been heard running Polestar yet."] = "Personne d'autre dans votre groupe n'a encore été détecté avec Polestar."
L["You have no step to sync to: open a guide you haven't finished."] = "Vous n'avez aucune étape à synchroniser : ouvrez un guide que vous n'avez pas fini."
L["You asked a moment ago: wait %d seconds."] = "Vous avez demandé il y a un instant : attendez %d secondes."
L["The game didn't send it: try again in a moment."] = "Le jeu ne l'a pas envoyé : réessayez dans un instant."
L["Asked your party to sync to your step. Each of them chooses."] = "Synchro sur votre étape proposée à votre groupe. Chacun choisit."
L["%s asked you to sync to their guide; that prompt can't show with the gamepad interface."] = "%s vous a proposé de vous synchroniser sur son guide ; cette demande ne peut pas s'afficher avec l'interface manette."
L["%s is on Polestar %s: your guides can differ. A newer version is out."] = "%s utilise Polestar %s : vos guides peuvent différer. Une version plus récente est disponible."
L["%s is on Polestar %s: your guides can differ."] = "%s utilise Polestar %s : vos guides peuvent différer."
L["Party sync is on: you and your party see each other's quest progress. Turn it off in Options."] = "La synchro de groupe est active : vous et votre groupe voyez la progression de quêtes des uns et des autres. Désactivez-la dans les Options."
L["Ask other players' Polestar which version it is"] = "Demander leur version aux Polestar des autres joueurs"
L["Up to 10 hidden addon whispers a session, to players of your faction you target or mouse over outside cities, combat and dungeons, and an answer to theirs: only the version number, so Polestar can tell you when a newer one is out. Off: none sent or answered."] = "Jusqu'à 10 chuchotements d'addon invisibles par session, aux joueurs de votre faction que vous ciblez ou survolez hors des villes, des combats et des donjons, et une réponse aux leurs : seulement le numéro de version, pour que Polestar puisse vous dire quand une version plus récente est sortie. Désactivé : rien n'est envoyé ni répondu."

