-- Gear/Options.lua
L["Automatic (talents)"] = "Automatique (talents)"
L["Rewards & gear"] = "Récompenses et équipement"
L["Gear advice"] = "Conseils d'équipement"
L["Score items for your class and talents and point out upgrades."] = "Évaluer les objets selon votre classe et vos talents et signaler les améliorations."
L["Stat weights"] = "Pondérations"
L["Which levelling weights score your items. Automatic follows the talent tree with the most points."] = "Pondérations de progression utilisées. Automatique suit l'arbre de talents le plus rempli."
L["Tooltip comparison"] = "Comparaison dans la bulle d'aide"
L["Show on item tooltips how much better or worse an item is than what you wear."] = "Afficher dans la bulle d'aide d'un objet à quel point il est meilleur ou pire que le vôtre."
L["Reward pick in the guide"] = "Récompense conseillée dans le guide"
L["Under a turn-in step, name the reward to take: an upgrade with its gain, else the best one you can use. The marks on the game's reward panel are under Quest rewards."] = "Sous une étape de rendu, nommer la récompense à prendre : une amélioration avec son gain, sinon la meilleure utilisable. Les marques du panneau de récompenses sont sous Récompenses de quête."
L["Reward pick on tooltips"] = "Récompense conseillée en bulle d'aide"
L["On a quest reward's tooltip, say whether it is the upgrade to take."] = "Dans la bulle d'aide d'une récompense de quête, indiquer si c'est l'amélioration à prendre."
L["Upgrade threshold"] = "Seuil d'amélioration"
L["Smaller gains than this are not called upgrades."] = "Les gains plus faibles ne comptent pas comme améliorations."
L["Pair with bag items"] = "Associer aux objets des sacs"
L["Against a worn two-hander, weigh a one-hander together with the best off-hand piece in your bags."] = "Face à une arme à deux mains portée, évaluer une arme à une main avec la meilleure main gauche de vos sacs."
L["Upgrade arrows in bags"] = "Flèches d'amélioration dans les sacs"
L["A green arrow on each item in your bags that is an upgrade for your spec, in the game's bags and in Baganator."] = "Une flèche verte sur chaque objet de vos sacs qui est une amélioration pour votre spécialisation, dans les sacs du jeu et dans Baganator."
L["Manage custom weights"] = "Gérer les pondérations personnalisées"
L["Import a Pawn scale string, and use, rename, export or delete the scales you have."] = "Importer une chaîne d'échelle Pawn, et utiliser, renommer, exporter ou supprimer vos échelles."
L["Leave bag arrows to Pawn"] = "Laisser les flèches des sacs à Pawn"
L["Pawn is installed and draws its own upgrade arrows in your bags. Turn this on to hide Polestar's, so an item does not carry two."] = "Pawn est installé et affiche ses propres flèches d'amélioration dans vos sacs. Activez ceci pour masquer celles de Polestar, afin qu'un objet n'en porte pas deux."
L["Manage"] = "Gérer"

-- Maps/Maps.lua
L["Dungeons and travel"] = "Donjons et voyages"
L["Dungeon entrances"] = "Entrées de donjon"
L["Marks each dungeon entrance with its level range. Click to open the dungeon's guide, or to set a waypoint when there is none; Shift-click always sets a waypoint. Needs the Codex pack."] = "Marque chaque entrée de donjon avec sa tranche de niveaux. Cliquez pour ouvrir le guide du donjon, ou placer un point de passage s'il n'y en a pas ; Maj-clic place toujours un point de passage. Nécessite le pack Codex."
L["Flight masters"] = "Maîtres de vol"
L["Your faction's and neutral flight masters: green when known, amber when not yet discovered. The tooltip lists destinations and flight times."] = "Maîtres de vol de votre faction et neutres : verts si connus, ambre si pas encore découverts. La bulle d'aide liste destinations et durées de vol."
L["Boats and zeppelins"] = "Bateaux et zeppelins"
L["Docks, zeppelin towers and the Deeprun Tram, with where they go."] = "Quais, tours des zeppelins et Tram des profondeurs, avec leurs destinations."
L["Inns"] = "Auberges"
L["Innkeepers; the one your Hearthstone is bound to is marked."] = "Aubergistes ; celui de votre pierre de foyer est marqué."
L["Travel icons on the minimap"] = "Icônes de voyage sur la minicarte"
L["Shows the flight masters, docks and inns turned on here on the minimap as well."] = "Affiche aussi sur la minicarte les maîtres de vol, quais et auberges activés ici."
L["Unexplored areas"] = "Zones inexplorées"
L["Shows the parts of each zone you have not explored yet, so the whole map is there before you visit. Tinted keeps them apart from where you have been."] = "Affiche les parties de chaque zone pas encore explorées, pour avoir toute la carte avant d'y aller. Teinté les distingue des lieux visités."
L["Hidden"] = "Masquées"
L["Revealed"] = "Révélées"
L["Revealed and tinted"] = "Révélées et teintées"
L["Zone level ranges"] = "Niveaux des zones"
L["Shows each zone's level range on the continent and zone maps, coloured by difficulty for your level."] = "Affiche la tranche de niveaux de chaque zone sur les cartes, colorée selon la difficulté pour votre niveau."
L["Coordinates"] = "Coordonnées"
L["Shows your position and the cursor's position under the world map."] = "Affiche votre position et celle du curseur sous la carte du monde."
L["Coordinates on the minimap"] = "Coordonnées sur la minicarte"
L["A small readout of your position at the bottom of the minimap."] = "Petit affichage de votre position en bas de la minicarte."
L["Quality of Life"] = "Confort de jeu"
L["Travel"] = "Voyages"
L["Flight timer"] = "Minuteur de vol"
L["While flying, shows the destination and the time left. Learns each route's real duration for this character; drag to move."] = "En vol, affiche la destination et le temps restant. Apprend la vraie durée de chaque trajet pour ce personnage ; glissez pour déplacer."
L["Forget learned flight times"] = "Oublier les durées de vol apprises"
L["Clears this character's recorded flight durations; estimates are used until they are flown again."] = "Efface les durées de vol enregistrées de ce personnage ; des estimations servent jusqu'au prochain vol."
L["Learned flight times cleared."] = "Durées de vol apprises effacées."
L["Trackers"] = "Suivis"
L["Instances"] = "Instances"
L["Track instances"] = "Suivre les instances"
L["Records dungeon and raid entries, time and experience per run. /pole instances lists them."] = "Enregistre entrées en donjon et raid, durée et expérience par passage. /pole instances les liste."
L["Compact display"] = "Affichage compact"
L["Shows the hourly instance count and the current run while it matters; drag to move."] = "Affiche le nombre d'instances de l'heure et le passage en cours quand c'est utile ; glissez pour déplacer."
L["Instances per hour"] = "Instances par heure"
L["Classic allows 5 new instances per hour per account. Forever may differ; adjust if it does."] = "Classic autorise 5 nouvelles instances par heure et par compte. Forever peut différer ; ajustez si besoin."
L["Instances per day"] = "Instances par jour"
L["Classic Era allows 30 new instances per 24 hours per account; 0 ignores the daily cap. Forever may differ."] = "Classic Era autorise 30 nouvelles instances par 24 heures et par compte ; 0 ignore la limite quotidienne. Forever peut différer."
L["Clear instance history"] = "Effacer l'historique des instances"
L["Forgets recorded entries and runs (the server's own limit is not affected)."] = "Oublie les entrées et passages enregistrés (la limite du serveur n'est pas affectée)."
L["Minimap button"] = "Bouton de la minicarte"
L["Forget"] = "Oublier"
L["Minimap"] = "Minicarte"
L["A Polestar button on the edge of the minimap. Click to hide or show Polestar, right-click for a menu, drag to move it."] = "Un bouton Polestar au bord de la minicarte. Cliquez pour masquer ou afficher Polestar, clic droit pour un menu, faites-le glisser pour le déplacer."

