-- QoL/Options.lua
L["Off by default: %s does this too."] = "Désactivé par défaut : %s le fait aussi."
L["Buttons"] = "Boutons"
L["Action buttons"] = "Boutons d'action"
L["Quest item button"] = "Bouton d'objet de quête"
L["Highlight the step's item in your bags"] = "Mettre en évidence l'objet de l'étape dans vos sacs"
L["Polestar: step item"] = "Polestar : objet de l'étape"
L["A button for the current step's quest item, with count, cooldown and range. Bind it under Key Bindings > AddOns."] = "Un bouton pour l'objet de quête de l'étape en cours, avec nombre, temps de recharge et portée. Raccourci dans Raccourcis > AddOns."
L["Target button"] = "Bouton de ciblage"
L["Targets the current step's mobs by name, or the NPCs it sends you to when it has no mob; each click moves to the next name. Bindable."] = "Cible les monstres de l'étape en cours par leur nom, ou les PNJ vers qui elle t'envoie quand elle n'a pas de monstre ; chaque clic passe au nom suivant. Raccourci assignable."
L["Show who it targets"] = "Montrer qui il cible"
L["The target button's icon shows what you do next: talk, accept, turn in, kill or loot, a skull for an elite, rare or boss, or their face once you have seen them. Their name sits beside it, green for a friendly NPC, red for a mob, gold for an elite or rare, with small icons for the names after it."] = "L'icône du bouton de ciblage montre ce que tu fais ensuite : parler, accepter, rendre, tuer ou dépouiller, un crâne pour un élite, un rare ou un boss, ou son visage dès que tu l'as vu. Son nom s'affiche à côté, en vert pour un PNJ amical, en rouge pour un monstre, en or pour un élite ou un rare, avec de petites icônes pour les noms suivants."
L["Name new targets in chat"] = "Annoncer les nouvelles cibles dans le chat"
L["When the target button's names change, one line in chat lists them (\"Targeting: ...\"). Only you see it."] = "Quand les noms du bouton de ciblage changent, une ligne dans le chat les liste (« Cible : ... »). Toi seul la vois."
L["Targeting: %s"] = "Cible : %s"
L["Where the target's name shows around the target button: right, left, above or below."] = "Où le nom de la cible s'affiche autour du bouton de ciblage : à droite, à gauche, au-dessus ou en dessous."
L["Right"] = "Droite"
L["Left"] = "Gauche"
L["Above"] = "Au-dessus"
L["Below"] = "En dessous"
L["Reset button positions"] = "Réinitialiser les boutons"
L["Put the buttons back in their default spot."] = "Remet les boutons à leur place par défaut."
L["Quest rewards"] = "Récompenses de quête"
L["Mark quest rewards"] = "Marquer les récompenses"
L["On the reward choices, a green arrow marks each upgrade for your spec (with Gear advice on), a thin frame in your accent colour the one to take, and a coin the one that sells for most."] = "Parmi les récompenses, une flèche verte marque chaque amélioration pour votre spécialisation (avec les conseils d'équipement activés), un fin cadre de votre couleur d'accent celle à prendre, et une pièce celle qui se vend le plus cher."
L["Take the best reward"] = "Prendre la meilleure récompense"
L["Chooses that reward for you when you complete the quest. Hold Shift to choose yourself."] = "Choisit cette récompense pour vous quand vous rendez la quête. Maintenez Maj pour choisir vous-même."
L["Wear reward upgrades"] = "Équiper les améliorations"
L["Puts on what a turn-in gives when it is an upgrade for your spec (with Gear advice on), once it reaches your bags and you are out of combat. Hold Shift at the turn-in to skip."] = "Équipe la récompense quand c'est une amélioration pour votre spécialisation (avec les conseils d'équipement activés), dès qu'elle arrive dans vos sacs et que vous êtes hors combat. Maintenez Maj en rendant la quête pour passer."
L["Faster questing"] = "Quêtes plus rapides"
L["Instant quest text"] = "Texte de quête instantané"
L["Shows quest text at once instead of fading it in (Forever's own option)."] = "Affiche le texte de quête d'un coup au lieu d'un fondu (option de Forever)."
L["Skip single-option gossip"] = "Passer les dialogues à choix unique"
L["Faster auto-loot"] = "Fouille automatique rapide"
L["Takes the whole corpse at once when auto-loot is on."] = "Ramasse tout le butin d'un coup quand la fouille automatique est activée."
L["Hide combat errors"] = "Masquer les erreurs de combat"
L["Hides \"Not enough rage\", \"Out of range\" and cooldown messages. Other errors still show."] = "Masque « Pas assez de rage », « Hors de portée » et les messages de recharge. Les autres erreurs restent affichées."
L["Open the flight map"] = "Ouvrir la carte de vol"
L["Talking to a flight master opens the map directly. Hold Shift for the gossip."] = "Parler à un maître de vol ouvre directement la carte. Maintenez Maj pour le dialogue."
L["Mark the route's destination"] = "Marquer la destination"
L["Marks where the travel route flies next on the flight map. You still choose the flight."] = "Marque sur la carte de vol la prochaine destination de l'itinéraire. Vous choisissez toujours le vol."
L["Death"] = "Mort"
L["Corpse or Spirit Healer"] = "Cadavre ou esprit guérisseur"
L["As a ghost, points the arrow at the faster way back: your corpse or the nearest Spirit Healer."] = "En fantôme, la flèche pointe vers le retour le plus rapide : votre cadavre ou l'esprit guérisseur le plus proche."
L["Release in battlegrounds"] = "Libérer en champ de bataille"
L["Releases your spirit at once when you die in a battleground, unless you can resurrect yourself or someone offers to. Hold Shift to stay."] = "Libère votre esprit dès votre mort en champ de bataille, sauf si vous pouvez vous ressusciter ou si quelqu'un le propose. Maintenez Maj pour rester."
L["Social"] = "Social"
L["Requests"] = "Demandes"
L["Accept summons"] = "Accepter les invocations"
L["Takes a summon at once, unless you are in combat. Hold Shift to decide yourself."] = "Accepte aussitôt une invocation, sauf en combat. Maintenez Maj pour décider vous-même."
L["Accept resurrections"] = "Accepter les résurrections"
L["Takes a resurrection as soon as it can, unless the caster is in combat. Never in Hardcore. Hold Shift to decide yourself."] = "Accepte une résurrection dès que possible, sauf si le lanceur est en combat. Jamais en Hardcore. Maintenez Maj pour décider vous-même."
L["Join friends' parties"] = "Rejoindre les groupes d'amis"
L["Accepts party invitations from friends, Battle.net friends and your guild, unless joining would leave a queue. Hold Shift to decide yourself."] = "Accepte les invitations de groupe de vos amis, amis Battle.net et de votre guilde, sauf si cela vous fait quitter une file d'attente. Maintenez Maj pour décider vous-même."
L["Blocking"] = "Blocage"
L["Decline other party invitations"] = "Refuser les autres invitations de groupe"
L["Declines party invitations from anyone who is not a friend or in your guild."] = "Refuse les invitations de groupe de quiconque n'est ni un ami ni dans votre guilde."
L["Decline guild invitations"] = "Refuser les invitations de guilde"
L["Declines guild invitations, except from friends."] = "Refuse les invitations de guilde, sauf celles d'amis."
L["Decline duels"] = "Refuser les duels"
L["Declines duel requests, except from friends and your guild."] = "Refuse les demandes de duel, sauf d'amis et de votre guilde."
L["Vendors"] = "Marchands"
L["Merchants"] = "Marchands"
L["Sell grey items"] = "Vendre les objets gris"
L["Repairs all gear at merchants who can, when you can afford it. Hold Shift to skip."] = "Répare tout l'équipement chez les marchands qui le peuvent, si vous en avez les moyens. Maintenez Maj pour passer."
L["Guild bank first"] = "Banque de guilde d'abord"
L["When your guild rank may, the guild bank pays for repairs and your money covers the rest."] = "Si votre rang le permet, la banque de guilde paie les réparations et votre argent couvre le reste."
L["Buy for the guide"] = "Acheter pour le guide"
L["When the step asks you to buy something and the merchant sells it, buys what you still need after selling and repairing. Optional buys and anything over 50g are left to you. Hold Shift to skip."] = "Quand l'étape demande d'acheter quelque chose que le marchand vend, achète ce qu'il vous manque après vente et réparation. Les achats facultatifs et ceux de plus de 50 po vous sont laissés. Maintenez Maj pour passer."
L["Trainers"] = "Maîtres"
L["Experience"] = "Expérience"
L["XP tracker"] = "Suivi d'XP"
L["XP per hour, time, kills and quests to level, and level splits (/pole xp)."] = "XP par heure, temps, victimes et quêtes avant le niveau suivant, et temps par niveau (/pole xp)."
L["Reset session"] = "Réinitialiser la session"
L["Start this session's XP per hour from zero."] = "Remet à zéro l'XP par heure de cette session."
L["Mark what they target"] = "Marquer leurs cibles"
L["A new one each press"] = "Une nouvelle à chaque appui"
L["Icon on mobs"] = "Icône sur les monstres"
L["A new one each press skips the NPCs' icon and leaves a mob that has one as it is."] = "« Une nouvelle à chaque appui » évite l'icône des PNJ et laisse tel quel un monstre qui en a déjà une."
L["Icon on NPCs"] = "Icône sur les PNJ"
L["A new one each press, so the last few NPCs keep theirs. Every press counts, even one that marks nothing."] = "Une nouvelle à chaque appui, pour que les derniers PNJ gardent la leur. Chaque appui compte, même s'il ne marque rien."
L["Rare button"] = "Bouton de rare"
L["Shows a button that targets a rare Polestar spotted nearby, until it dies or is out of sight. Bindable."] = "Affiche un bouton qui cible un rare repéré à proximité par Polestar, jusqu'à sa mort ou sa disparition. Raccourci possible."
L["Guide level on the XP bar"] = "Niveau du guide sur la barre d'XP"
L["A mark at the end of the game's XP bar with the level the guide wants you to reach before it moves on, and how many levels away that is when it is more than one."] = "Une marque au bout de la barre d'XP du jeu avec le niveau que le guide veut vous voir atteindre avant de passer à la suite, et combien de niveaux il reste quand il y en a plus d'un."
L["Hearthstone"] = "Pierre de foyer"
L["Set your home at the guide's inn"] = "Définir votre lieu de repos à l'auberge du guide"
L["When the step sets your home and you talk to its innkeeper, binds your Hearthstone there. Never at another inn. Hold Shift to skip."] = "Quand l'étape définit votre lieu de repos et que vous parlez à l'aubergiste, lie votre Pierre de foyer à cet endroit. Jamais dans une autre auberge. Maintenez Maj pour ignorer."
L["Riding reminder"] = "Rappel de monte"
L["At level 40 and 60, if you have not learned riding yet, says the cost in chat (with any Honored discount) and points the arrow at your race's riding trainer when you can afford it. Warlocks and Alliance Paladins are sent to their free-mount quest NPC instead. Once per tier per character."] = "Aux niveaux 40 et 60, si vous n'avez pas encore appris la monte, indique le coût dans la discussion (avec la remise Honoré éventuelle) et dirige la flèche vers le maître de monte de votre race quand vous en avez les moyens. Les démonistes et les paladins de l'Alliance sont plutôt envoyés au PNJ de leur quête de monture gratuite. Une fois par palier et par personnage."
L["Hide the game's quest tracker"] = "Masquer le suivi des quêtes du jeu"
L["Hides the game's tracker on the right of the screen, with its quests, achievements and professions, as Questie can. Not with the gamepad interface."] = "Masque le suivi du jeu à droite de l'écran, avec ses quêtes, hauts faits et métiers, comme Questie peut le faire. Pas avec l'interface manette."
L["Reset"] = "Réinitialiser"
L["The item the current step uses, or a quest item it collects, glows in your bags (and in Baganator). An item a later step needs gets a lock, so you don't sell it."] = "L'objet qu'utilise l'étape en cours, ou un objet de quête qu'elle fait ramasser, brille dans vos sacs (et dans Baganator). Un objet requis par une étape ultérieure reçoit un cadenas, pour que vous ne le vendiez pas."
L["Offer gear upgrades"] = "Proposer les améliorations"
L["When gear from a kill, a chest or a merchant is an upgrade for your spec (with Gear advice on), the guide window offers to put it on. Nothing goes on until you press Wear it; Not this one stops it asking about that item."] = "Quand une pièce d'équipement obtenue sur une victime, dans un coffre ou chez un marchand est une amélioration pour votre spécialisation (avec les conseils d'équipement activés), la fenêtre du guide propose de l'équiper. Rien n'est équipé avant que vous appuyiez sur « L'équiper » ; « Pas celui-ci » arrête les questions sur cet objet."
L["Sells Poor-quality items, and anything you marked as junk, when a merchant opens and prints the total. Never an item marked to keep or one a later step needs."] = "Vend les objets de qualité médiocre, et tout ce que vous avez marqué comme camelote, à l'ouverture d'un marchand, et affiche le total. Jamais un objet marqué à garder ni un objet requis par une étape ultérieure."
L["Restock button"] = "Bouton de réapprovisionnement"
L["At a merchant that sells what you are short of, a Restock button under its window buys up to the amounts below (this character's). Nothing is bought until you press it. Other items, such as reagents: /polestar restock <item> <amount>."] = "Chez un marchand qui vend ce qui vous manque, un bouton de réapprovisionnement sous sa fenêtre achète jusqu'aux quantités ci-dessous (celles de ce personnage). Rien n'est acheté avant que vous appuyiez dessus. Autres objets, comme les réactifs : /polestar restock <objet> <quantité>."
L["Keeps this many drinks in your bags. The merchant's best one for your level is bought."] = "Garde ce nombre de boissons dans vos sacs. La meilleure du marchand pour votre niveau est achetée."
L["Keeps this much food in your bags. The merchant's best one for your level is bought."] = "Garde cette quantité de nourriture dans vos sacs. La meilleure du marchand pour votre niveau est achetée."
L["Keeps this many arrows or shot for the bow, crossbow or gun you wear."] = "Garde ce nombre de flèches ou de balles pour l'arc, l'arbalète ou l'arme à feu que vous portez."
L["Bags"] = "Sacs"
L["When your bags are nearly full, a button shows the free slots and the cheapest junk in them, and while the step collects something the guide window says so too. Press twice to delete that junk: grey items, or common ones you marked as junk. Bindable."] = "Quand vos sacs sont presque pleins, un bouton affiche les emplacements libres et la camelote la moins chère qu'ils contiennent, et la fenêtre du guide le signale aussi pendant que l'étape fait ramasser quelque chose. Appuyez deux fois pour supprimer cette camelote : objets gris, ou objets communs marqués comme camelote. Raccourci possible."
L["Nearly full at"] = "Presque pleins à"
L["%d slot"] = "%d emplacement"
L["%d slots"] = "%d emplacements"
L["How many free slots or fewer count as nearly full."] = "Nombre d'emplacements libres (ou moins) à partir duquel les sacs sont presque pleins."
L["Junk and keep marks"] = "Marques camelote et à garder"
L["Ctrl+Alt-click an item in your bags to mark it as junk, again to keep it, and again to clear it. Junk is sold with the grey items; a kept item is never sold or deleted."] = "Ctrl+Alt-clic sur un objet de vos sacs pour le marquer comme camelote, encore une fois pour le garder, et encore une fois pour effacer la marque. La camelote est vendue avec les objets gris ; un objet gardé n'est jamais vendu ni supprimé."
L["Step key talks and loots"] = "La touche d'étape parle et fouille"
L["Once the step key has targeted the step's NPC, the next press talks to it; on the corpse of the step's mob, it loots; in the step's quest window, it accepts or completes. Only out of combat, and only on the step the guide is at."] = "Une fois que la touche d'étape a ciblé le PNJ de l'étape, l'appui suivant lui parle ; sur le cadavre du monstre de l'étape, elle fouille ; dans la fenêtre de quête de l'étape, elle accepte ou termine. Seulement hors combat, et seulement à l'étape où se trouve le guide."
L["Warn when out of breath"] = "Avertir en cas de manque d'air"
L["Under water, a red edge round the screen, a sound and a taskbar flash with 10 seconds of breath left, and again at 4."] = "Sous l'eau, un bord rouge autour de l'écran, un son et un clignotement de la barre des tâches quand il reste 10 secondes de souffle, puis à nouveau à 4."
L["Pick what the step asks for"] = "Choisir ce que demande l'étape"
L["At the step's NPC, picks the chat option the guide names, or opens the goods or training the step needs. Only on the step the guide is at. Hold Shift to choose yourself."] = "Auprès du PNJ de l'étape, choisit l'option de dialogue indiquée par le guide, ou ouvre les marchandises ou l'apprentissage dont l'étape a besoin. Seulement à l'étape où se trouve le guide. Maintenez Maj pour choisir vous-même."
L["Picks the only option of NPCs without quests. Hold Shift to read it. Off, the game still skips some itself, Pick what the step asks for still picks the step's option, and flight masters follow Open the flight map."] = "Choisit l'unique option des PNJ sans quête. Maintenez Maj pour la lire. Désactivé, le jeu en passe encore certaines lui-même, « Choisir ce que demande l'étape » choisit toujours l'option de l'étape, et les maîtres de vol suivent « Ouvrir la carte de vol »."
L["Click objectives to target"] = "Cibler en cliquant sur les objectifs"
L["Clicking an objective row or NPC heading also targets its NPC outside combat, using the same marking settings as the Target button. This replaces your current target; a failed search clears it."] = "Un clic sur une ligne d'objectif ou sur le nom d'un PNJ en tête cible aussi ce PNJ hors combat, avec les mêmes réglages de marquage que le bouton de ciblage. Cela remplace votre cible actuelle ; une recherche infructueuse la retire."
L["The target button and the step key put a raid icon on the mob and the NPC they target; out of combat, a press that finds neither clears your target. Pressing again never takes an icon off. In a party you don't lead, only a unit with no icon gets one; in a raid, only when you lead or assist."] = "Le bouton de ciblage et la touche d'étape placent une icône de raid sur le monstre et le PNJ qu'ils ciblent ; hors combat, un appui qui ne trouve ni l'un ni l'autre retire votre cible. Un nouvel appui ne retire jamais d'icône. Dans un groupe que vous ne menez pas, seule une unité sans icône en reçoit une ; en raid, seulement si vous êtes chef ou assistant."
L["Ping what they target"] = "Pinger leurs cibles"
L["The target button and the step key ping the mob they target, so your group sees it behind rocks and buildings. Never in a raid unless you lead or assist. The rare buttons always ping."] = "Le bouton de ciblage et la touche d'étape pinguent le monstre qu'ils ciblent, pour que votre groupe le voie derrière les rochers et les bâtiments. Jamais en raid, sauf si vous êtes chef ou assistant. Les boutons de rare pinguent toujours."
L["Show quest-starting loot"] = "Afficher le butin qui lance une quête"
L["When you loot an item that starts a quest you can take, it goes on the quest item button with a glow until you click it or take the quest. The step's own item comes first; several wait their turn, oldest first."] = "Quand vous ramassez un objet qui lance une quête que vous pouvez prendre, il va sur le bouton d'objet de quête avec une lueur jusqu'à ce que vous cliquiez dessus ou preniez la quête. L'objet de l'étape passe en premier ; s'il y en a plusieurs, ils attendent leur tour, le plus ancien d'abord."
L["Track only dungeon quests in dungeons"] = "En donjon, suivre seulement les quêtes du donjon"
L["Inside a dungeon or raid, the game's quest tracker and Polestar's quest markers show only that instance's quests. The quests you were tracking come back when you leave, even after a reload inside."] = "Dans un donjon ou un raid, le suivi des quêtes du jeu et les marqueurs de quête de Polestar n'affichent que les quêtes de cette instance. Les quêtes que vous suiviez reviennent quand vous sortez, même après un rechargement à l'intérieur."
L["New spells at level-up"] = "Nouveaux sorts au gain de niveau"
L["When you level up, a card on the guide window shows the class spells you can now train, what they cost together and the nearest class trainer, with a button for the arrow. Not in combat or instances, and not on levels with nothing new."] = "Quand vous gagnez un niveau, une carte sur la fenêtre du guide montre les sorts de classe que vous pouvez maintenant apprendre, leur coût total et le maître de classe le plus proche, avec un bouton pour la flèche. Pas en combat ni en instance, et pas aux niveaux sans rien de nouveau."
L["Old ranks on your bars"] = "Anciens rangs sur vos barres"
L["After training and at login, says which spells on your action bars are a lower rank than the one in your spellbook, with a button that puts the highest rank in the same buttons (out of combat). Macros and items are never touched. Right-click a spell on the card to keep it at its rank; a lower rank you put on a bar yourself is kept too."] = "Après l'entraînement et à la connexion, indique quels sorts de vos barres d'action sont d'un rang inférieur à celui de votre grimoire, avec un bouton qui place le rang le plus élevé sur les mêmes boutons (hors combat). Les macros et les objets ne sont jamais touchés. Clic droit sur un sort de la carte pour le garder à son rang ; un rang inférieur que vous placez vous-même sur une barre est gardé aussi."
L["Forget kept ranks"] = "Oublier les rangs gardés"
L["Lists the spells you kept at a lower rank again."] = "Liste de nouveau les sorts que vous avez gardés à un rang inférieur."
L["Boosted Rest status"] = "État du Repos amplifié"
L["How long the campfire's Boosted Rest lasts and the Cozy Sleeping Bag's cooldown, under the guide window's XP line; your party's Boosted Rest in the party panel."] = "La durée restante du Repos amplifié du feu de camp et le temps de recharge du Sac de couchage douillet, sous la ligne d'XP de la fenêtre du guide ; le Repos amplifié de votre groupe dans le panneau du groupe."
L["Take the marked flight"] = "Prendre le vol marqué"
L["When the flight map opens, flies to the marked destination. Hold Shift at the flight master to choose yourself."] = "Quand la carte de vol s'ouvre, vole vers la destination marquée. Maintenez Maj auprès du maître de vol pour choisir vous-même."
