-- Dungeons/Dungeons.lua
L["Dungeon quests, bosses and entrances"] = "Quêtes, boss et entrées des donjons"
L["Dungeons"] = "Donjons"
L["A page per dungeon and raid: every quest with where to get it, its chain and rewards, the bosses and the entrance."] = "Une page par donjon et raid : chaque quête avec où l'obtenir, sa suite et ses récompenses, les boss et l'entrée."
L["Kill %d %s"] = "Tuer %d %s"
L["Collect %s"] = "Ramasser %s"
L["Collect %d %s"] = "Ramasser %d %s"
L["Use %s"] = "Utiliser %s"
L["Dungeons in leveling guides"] = "Donjons dans les guides de montée en niveau"
L["Off: the guide skips this group quest and keeps to the solo route. Until you choose, it asks when it gets there."] = "Désactivé : le guide passe cette quête de groupe et s'en tient à l'itinéraire solo. Tant que vous n'avez pas choisi, il pose la question en y arrivant."
L["Group quests"] = "Quêtes de groupe"
L["Group quests in leveling guides"] = "Quêtes de groupe dans les guides de montée en niveau"
L["Tell me when a dungeon opens up"] = "Me prévenir quand un donjon devient accessible"
L["When a level-up opens a dungeon's quests to this character, a card on the guide window says so, once per dungeon, with a button that picks up its quests in a new tab."] = "Quand un gain de niveau ouvre les quêtes d'un donjon à ce personnage, une carte sur la fenêtre du guide l'indique, une fois par donjon, avec un bouton qui prend ses quêtes dans un nouvel onglet."
L["Entrance in Horde territory (outside the Undercity)"] = "Entrée en territoire de la Horde (devant Fossoyeuse)"
L["Entrance in Alliance territory (in Ironforge)"] = "Entrée en territoire de l'Alliance (à Forgefer)"
L["Entrance in Horde territory (in Orgrimmar)"] = "Entrée en territoire de la Horde (à Orgrimmar)"
L["Entrance in Alliance territory (in Stormwind)"] = "Entrée en territoire de l'Alliance (à Hurlevent)"
L["Leveling guides take you through this dungeon where they have steps for it. Off: they keep to the solo route. More dungeons join this list as they are added to the guides' route."] = "Les guides de montée en niveau vous font passer par ce donjon quand ils ont des étapes pour lui. Désactivé : ils s'en tiennent à l'itinéraire solo. D'autres donjons rejoignent cette liste à mesure qu'ils sont ajoutés à l'itinéraire des guides."
L["Speak with %s"] = "Parler à %s"
-- L["Dungeons are turned off (Options > Discovery > Lookup)."] = ""

-- Dungeons/Pickup.lua
L["Quest giver"] = "Donneur de quête"
L["In your log already: %s"] = "Déjà dans votre journal : %s"
L["After the run: choose Hand in the quests at the end of this guide or on the dungeon's page."] = "Après le donjon : choisissez Rendre les quêtes à la fin de ce guide ou sur la page du donjon."
L["%s: pick up the quests"] = "%s : prendre les quêtes"
L["Pick up the quests from level %d"] = "Prendre les quêtes à partir du niveau %d"
L["Pick up the quests (%d now · %d at level %d)"] = "Prendre les quêtes (%d maintenant · %d au niveau %d)"
L["Pick up the quests (%d now · %d from level %d)"] = "Prendre les quêtes (%d maintenant · %d à partir du niveau %d)"
L["%s: level %d, needs %s first"] = "%s : niveau %d, nécessite d'abord %s"
L["%s: level %d"] = "%s : niveau %d"
L["Comes back at level %d: %s"] = "Revient au niveau %d : %s"
L["Level %d: you can take %s now. Its giver is marked on your map; pick up the quests again to add it to the guide."] = "Niveau %d : vous pouvez prendre %s maintenant. Son donneur est marqué sur votre carte ; reprenez les quêtes pour l'ajouter au guide."
