-- Dungeons/Attune.lua
L["%s drops it inside %s."] = "%s le laisse tomber dans %s."
L["%s: %s"] = "%s : %s"
L["Lets Lothos Riftwaker in Blackrock Mountain send you to the Molten Core; without it, walk in through Blackrock Depths."] = "Permet à Lothos Fendefaille, au mont Rochenoire, de vous envoyer au Cœur du Magma ; sans cela, entrez à pied par les profondeurs de Rochenoire."
L["Douses the Molten Core's runes; Majordomo Executus comes out only when every rune is doused. Duke Hydraxis hands it out once Hands of the Enemy is done."] = "Éteint les runes du Cœur du Magma ; le majordome Executus n'apparaît que lorsque toutes les runes sont éteintes. Le duc Hydraxis le remet une fois Les mains de l'ennemi terminée."
L["Everyone entering Onyxia's Lair carries the Drakefire Amulet."] = "Toute personne entrant dans le repaire d'Onyxia porte l'Amulette de feu draconique."
L["Lets you touch the Orb of Command in Upper Blackrock Spire to reach Blackwing Lair; without it, walk in through the spire."] = "Vous permet de toucher l'Orbe de commandement au sommet du pic Rochenoire pour atteindre le repaire de l'Aile noire ; sans cela, entrez à pied par le pic."
L["Everyone entering Naxxramas needs it; which of the three quests you take depends on your standing with the Argent Dawn."] = "Toute personne entrant dans Naxxramas en a besoin ; laquelle des trois quêtes vous prenez dépend de votre réputation auprès de l'Aube d'argent."
L["Opens Scholomance's gate; one key opens it for the group."] = "Ouvre la grille de Scholomance ; une clé l'ouvre pour tout le groupe."
L["Opens the Shadowforge gates in Blackrock Depths; one key opens them for the group."] = "Ouvre les portes de Forgeombre dans les profondeurs de Rochenoire ; une clé les ouvre pour tout le groupe."
L["Opens the cells of Blackrock Depths' prison."] = "Ouvre les cellules de la prison des profondeurs de Rochenoire."
L["Opens the Eastwall Gate into Stratholme's Scourge-held districts."] = "Ouvre la porte du Mur Est vers les quartiers de Stratholme tenus par le Fléau."
L["Opens the inner doors of Dire Maul's North and West wings."] = "Ouvre les portes intérieures des ailes Nord et Ouest de Hache-Tripes."
L["Opens Gnomeregan's back door, the Workshop entrance."] = "Ouvre la porte arrière de Gnomeregan, l'entrée de l'Atelier."
L["Opens the doors of the Armory and the Cathedral."] = "Ouvre les portes de l'Armurerie et de la Cathédrale."
L["Opens the gate of the Horde's way into the City of Dalaran; one key opens it for the group. The Alliance walks in through the sewer pipe in Cantrips & Crows."] = "Ouvre la porte de l'accès de la Horde à la cité de Dalaran ; une seule clé l'ouvre pour tout le groupe. L'Alliance entre par la canalisation des égouts de Cantrips & Crows."

