L["The shortest walk. Cuts across fields and goes straight over hills."] = "Le chemin le plus court. Coupe à travers champs et passe droit par les collines."
L["Takes roads when they aren't much longer, and goes round steep hills."] = "Prend les routes si elles ne sont pas beaucoup plus longues, et contourne les collines raides."
L["Stays on roads, even when it's longer. Slower, but easy to follow."] = "Reste sur les routes, même si c'est plus long. Plus lent, mais facile à suivre."
L["Every style keeps you out of the other faction's towns and away from zones far above your level."] = "Chaque style vous tient à l'écart des villes de l'autre faction et des zones bien au-dessus de votre niveau."
L["Supplies"] = "Fournitures"
L["your next stop"] = "votre prochain arrêt"
L["Points the way. The map marks each place."] = "Montre le chemin. La carte marque chaque lieu."
L["The background of every Polestar window. It changes as you pick."] = "Le fond de chaque fenêtre de Polestar. Il change selon votre choix."
L["Skip keeps these as they are."] = "Passer les laisse tels quels."
L["How the arrow walks you. Change it any time in Options."] = "Comment la flèche vous guide. Modifiable à tout moment dans les Options."
L["%s opens the guide window on the right. The arrow points at your first stop."] = "%s ouvre la fenêtre du guide à droite. La flèche pointe vers votre premier arrêt."
L["Played to the end in tests, but not yet by players. If a step is wrong, press %s in the guide window and tell us on Discord."] = "Joué jusqu'au bout en test, mais pas encore par des joueurs. Si une étape est fausse, appuyez sur %s dans la fenêtre du guide et dites-le-nous sur Discord."
L["Feedback, bug reports and news."] = "Avis, signalements de bugs et nouveautés."
