L["The link is selected for you: copy it with Ctrl+C (Cmd+C on a Mac), paste it in your browser's address bar, check the form and press Create."] = "Le lien est sélectionné pour vous : copiez-le avec Ctrl+C (Cmd+C sur Mac), collez-le dans la barre d'adresse de votre navigateur, vérifiez le formulaire et appuyez sur « Create »."
L["Mark here"] = "Marquer ici"
L["Cancel"] = "Annuler"
L["Walk to where the step should have sent you: the NPC, the object or the mobs as you found them. Then press Mark here. Your report is kept while you walk."] = "Marchez jusqu'à l'endroit où l'étape aurait dû vous envoyer : le PNJ, l'objet ou les monstres tels que vous les avez trouvés. Puis appuyez sur « Marquer ici ». Votre rapport est conservé pendant que vous marchez."
L["Clear mark"] = "Effacer la marque"
L["Report it on Discord"] = "Le signaler sur Discord"
L["1. Press Copy report, then Ctrl+C (Cmd+C on a Mac).\n2. In the Polestar Discord, open #bugs and press New Post. Not in it yet? Get the invite.\n3. Paste the report, give it a short title and post it. A bot files it for the developers and tells you in your thread when it's fixed."] = "1. Appuyez sur « Copier le rapport », puis Ctrl+C (Cmd+C sur Mac).\n2. Sur le Discord de Polestar, ouvrez #bugs et appuyez sur « Nouvelle publication ». Pas encore membre ? Obtenez l'invitation.\n3. Collez le rapport, donnez-lui un titre court et publiez-le. Un bot le transmet aux développeurs et vous prévient dans votre fil quand c'est corrigé."
L["Have a GitHub account? Open the issue there with everything filled in."] = "Vous avez un compte GitHub ? Ouvrez-y le ticket avec tout déjà rempli."
