L["Copy report"] = "Copier le rapport"
L["1 problem"] = "1 problème"
L["%d problems"] = "%d problèmes"
L["Hide"] = "Masquer"
L["No community addons installed."] = "Aucun addon communautaire installé."
L["Suggestions"] = "Suggestions"
L["Suggest guides from"] = "Suggérer les guides de"
L["Where the guide for your level is suggested from. Polestar's guides fill in where a community addon has none for you."] = "D'où vient le guide suggéré pour votre niveau. Les guides de Polestar prennent le relais là où un addon communautaire n'en a pas pour vous."
L["About community guides"] = "À propos des guides de la communauté"
L["A community addon is a separate addon with someone else's guides for Polestar. It is not part of Polestar, and its guides are not Polestar's own routes."] = "Un addon communautaire est un addon séparé contenant les guides de quelqu'un d'autre pour Polestar. Il ne fait pas partie de Polestar, et ses guides ne sont pas les itinéraires de Polestar."
L["Get a community addon from wherever its author publishes it and install it like any addon, then restart the game. Its guides appear in the guide menu under Community guides, with the author's name. The switch on its row above turns it on or off."] = "Procurez-vous un addon communautaire là où son auteur le publie et installez-le comme n'importe quel addon, puis redémarrez le jeu. Ses guides apparaissent dans le menu des guides sous Guides de la communauté, avec le nom de l'auteur. L'interrupteur de sa ligne ci-dessus l'active ou le désactive."
L["Each community addon is made and supported by its author: report its problems to them, not to Polestar. It is an addon like any other, so install community addons from authors you trust."] = "Chaque addon communautaire est créé et maintenu par son auteur : signalez-lui ses problèmes, pas à Polestar. C'est un addon comme un autre, alors n'installez que des addons communautaires d'auteurs de confiance."
L["Anyone can make a community addon with Polestar's own tools."] = "Tout le monde peut créer un addon communautaire avec les outils de Polestar."
L["Community guides, explained"] = "Les guides de la communauté expliqués"
L["Installed"] = "Installés"
L["Read more:"] = "En savoir plus :"
L["Read more: docs/GUIDE_PACKS.md in Polestar's source"] = "En savoir plus : docs/GUIDE_PACKS.md dans les sources de Polestar"
L["Turn on and reload"] = "Activer et recharger"
L["Polestar Guides is turned off in the AddOns list, so Polestar has no guides to show. Turn it on for all your characters and reload?"] = "Polestar Guides est désactivé dans la liste des AddOns : Polestar n'a donc aucun guide à afficher. L'activer pour tous vos personnages et recharger ?"

