L["How the arrow, map tooltips, rares and the death helper show distances."] = "Unité des distances de la flèche, des bulles d'aide de la carte, des rares et de l'aide à la mort."
L["Yards (the game's unit)"] = "Mètres du jeu (yards)"
L["Metres"] = "Mètres"
L["Arrival sound"] = "Son d'arrivée"
L["A soft chime when you reach a waypoint."] = "Un léger carillon quand vous atteignez un point de passage."
L["Reset arrow position"] = "Réinitialiser la position de la flèche"
L["Back to the top of the screen. Drag the arrow to move it."] = "Retour en haut de l'écran. Faites glisser la flèche pour la déplacer."
L["Plan travel routes"] = "Planifier les trajets"
L["Flights, boats and your hearthstone when they are faster. Off: the arrow points straight at the goal."] = "Vols, bateaux et pierre de foyer quand c'est plus rapide. Désactivé : la flèche pointe droit sur l'objectif."
L["Walk real paths"] = "Suivre les vrais chemins"
L["The arrow follows paths on the ground around cliffs, water and walls, on Polestar's walking maps, with Shortest Path Forever's router by Cillian Berragan. Off: it points straight at each stop."] = "La flèche suit les chemins au sol en contournant falaises, eau et murs, sur les cartes de marche de Polestar, avec le calculateur d'itinéraire de Shortest Path Forever par Cillian Berragan. Désactivé : elle pointe tout droit vers chaque arrêt."
L["Route lines"] = "Lignes d'itinéraire"
L["Class teleports"] = "Téléportations de classe"
L["Routes may start with a Teleport spell you know (a mage's city teleports, a druid's Moonglade) when it is faster. A city teleport needs a Rune of Teleportation in your bags."] = "Un itinéraire peut commencer par un sort de téléportation que vous connaissez (les téléportations de mage vers les capitales, Reflet-de-Lune pour le druide) quand c'est plus rapide. Une téléportation vers une capitale demande une rune de téléportation dans vos sacs."
L["Share boat times"] = "Partager les horaires des bateaux"
L["Riding a boat, zeppelin, tram or lift times it; your guild and group get those times and you get theirs, so the arrow can say when the next one leaves."] = "Prendre un bateau, un zeppelin, un tram ou un ascenseur en relève l'horaire ; votre guilde et votre groupe reçoivent ces horaires et vous recevez les leurs, pour que la flèche dise quand part le prochain."
L["Blizzard waypoint"] = "Point de passage Blizzard"
L["Also set the game's own map pin and tracking."] = "Place aussi le repère et le suivi du jeu."
L["Mirror to TomTom"] = "Copier vers TomTom"
L["Adds the target as a TomTom waypoint when TomTom is loaded."] = "Ajoute la cible comme point de passage TomTom quand TomTom est chargé."
L["Use TomTom's arrow"] = "Utiliser la flèche de TomTom"
L["Hides Polestar's arrow in favour of TomTom's, except on the way to another continent, where TomTom's arrow cannot point."] = "Masque la flèche de Polestar au profit de celle de TomTom, sauf en route vers un autre continent, où la flèche de TomTom ne peut pas pointer."
L["Automation"] = "Automatisation"
L["Accept guide quests"] = "Accepter les quêtes du guide"
L["Only quests in the next steps of your open guides. Hold Shift to skip."] = "Uniquement les quêtes des prochaines étapes de vos guides ouverts. Maintenez Maj pour passer."
L["Turn in guide quests"] = "Rendre les quêtes du guide"
L["Never picks between rewards. Hold Shift to skip."] = "Ne choisit jamais entre des récompenses. Maintenez Maj pour passer."
L["Warn about missable quests"] = "Prévenir des quêtes qu'on peut manquer"
L["Before you take a quest that closes another for good, says which in chat and leaves the accept to you."] = "Avant de prendre une quête qui en ferme une autre pour de bon, dit laquelle dans le chat et vous laisse accepter vous-même."
L["Skip grey quests"] = "Passer les quêtes grises"
L["Leaves out grey quests and their turn-ins, unless a later quest needs them first."] = "Écarte les quêtes grises et leurs rendus, sauf si une quête ultérieure les requiert."
L["Pick a guide for me"] = "Choisir un guide pour moi"
L["Where to level next"] = "Où monter en niveau ensuite"
L["Where a guide offers more than one zone to continue in (/polestar path)."] = "Quand un guide propose plusieurs zones pour continuer (/polestar path)."
L["Let me choose"] = "Me laisser choisir"
L["Take the recommended zone"] = "Prendre la zone recommandée"
L["Trainer reminders"] = "Rappels de maître"
L["A note in the guide window, with the nearest trainer of your class, when new skills are waiting."] = "Une note dans la fenêtre du guide, avec le maître de classe le plus proche, quand de nouveaux sorts vous attendent."
L["Every 2 levels"] = "Tous les 2 niveaux"
L["Every level"] = "Chaque niveau"
L["Off"] = "Désactivé"
L["Accent"] = "Accent"
L["Click to pick your own, right-click to go back to the scheme's."] = "Cliquez pour choisir la vôtre, clic droit pour revenir à celle du thème."
L["Class colour"] = "Couleur de classe"
L["Polestar gold"] = "Or Polestar"
L["The accent follows your class: warlock purple, shaman blue, druid orange. Picking your own accent turns this off."] = "L'accent suit votre classe : violet démoniste, bleu chaman, orange druide. Choisir votre propre accent désactive cette option."
L["Match EllesmereUI accent"] = "Suivre l'accent d'EllesmereUI"
L["Follow EllesmereUI's accent, live. Picking your own accent turns this off."] = "Suit l'accent d'EllesmereUI en direct. Choisir votre propre accent désactive cette option."
L["Background"] = "Fond"
L["Background colour"] = "Couleur de fond"
L["The ground of every Polestar window. Right-click to go back to the scheme's. Text always stays legible: a colour too light for it is darkened."] = "Le fond de chaque fenêtre de Polestar. Clic droit pour revenir à celui du thème. Le texte reste toujours lisible : une couleur trop claire est assombrie."
L["Brightness"] = "Luminosité"
L["Lifts or lowers every background together. Right-click to reset."] = "Éclaircit ou assombrit tous les fonds ensemble. Clic droit pour réinitialiser."
L["The background opacity of every Polestar window: how much of the world shows through. Right-click to reset."] = "L'opacité du fond de chaque fenêtre de Polestar : à quel point le monde transparaît. Clic droit pour réinitialiser."
L["Font"] = "Police"
L["Game font"] = "Police du jeu"
L["Match EllesmereUI font"] = "Suivre la police d'EllesmereUI"
L["Follow EllesmereUI's font, live. Choosing another font turns this off."] = "Suit la police d'EllesmereUI en direct. Choisir une autre police désactive cette option."
L["Reduce motion"] = "Réduire les animations"
L["No sliding or popping; fades stay short."] = "Pas de glissements ni d'apparitions brusques ; les fondus restent courts."
L["Windows"] = "Fenêtres"
L["Window border"] = "Bordure de fenêtre"
L["The line around every Polestar window."] = "Le trait autour de chaque fenêtre de Polestar."
L["Border colour"] = "Couleur de bordure"
L["Click to pick your own, right-click to go back to the scheme's hairline."] = "Cliquez pour choisir la vôtre, clic droit pour revenir au filet du thème."
L["Hairline"] = "Filet"
L["Accent border"] = "Bordure d'accent"
L["The border takes your accent colour. Picking your own border colour turns this off."] = "La bordure prend votre couleur d'accent. Choisir votre propre couleur de bordure désactive cette option."
L["In screen pixels; a thicker border grows outward. Right-click to reset."] = "En pixels d'écran ; une bordure plus épaisse s'étend vers l'extérieur. Clic droit pour réinitialiser."
L["Starlit band"] = "Bande étoilée"
L["The night sky with its stars across the top of every window. Off: the plain background."] = "Le ciel nocturne étoilé en haut de chaque fenêtre. Désactivé : le fond uni."
L["Window shadow"] = "Ombre de fenêtre"
L["The soft shadow under every window."] = "L'ombre douce sous chaque fenêtre."
L["Guide window"] = "Fenêtre du guide"
L["Style"] = "Style"
L["Transparent drops every background and border; text is outlined and the controls appear when you hover the window."] = "Transparent retire fonds et bordures ; le texte est détouré et les commandes apparaissent au survol de la fenêtre."
L["Standard"] = "Standard"
L["Width"] = "Largeur"
L["Menu scale"] = "Échelle des menus"
L["The guide menu and this window; applies when you let go. Right-click to reset."] = "Le menu des guides et cette fenêtre ; s'applique au relâchement. Clic droit pour réinitialiser."
L["3D"] = "3D"
L["Flat"] = "Plate"
L["Arrow colour"] = "Couleur de la flèche"
L["The arrow on its way; the target's pin on the maps and the route's stops wear it too. Right-click to go back to the accent."] = "La flèche en chemin ; le repère de la cible sur les cartes et les étapes du trajet la reprennent aussi. Clic droit pour revenir à l'accent."
L["Jade"] = "Jade"
L["What Polestar draws on the world map and the minimap. Quest, rare and travel icons start off."] = "Ce que Polestar affiche sur la carte du monde et la minicarte. Les icônes de quêtes, de rares et de voyage sont désactivées par défaut."
L["Guide pins on the world map"] = "Repères du guide sur la carte du monde"
L["The arrow's target, the stops of its travel route, the step's other goals, the areas their mobs and objects spawn in, and the route lines."] = "La cible de la flèche, les arrêts de son itinéraire, les autres objectifs de l'étape, les zones où apparaissent leurs monstres et objets, et les lignes d'itinéraire."
L["Guide pin on the minimap"] = "Repère du guide sur la minicarte"
L["The arrow's target, the areas it spawns in, and the route line."] = "La cible de la flèche, les zones où elle apparaît, et la ligne d'itinéraire."
L["Trail dots along the travel route"] = "Points de piste le long du trajet"
L["Moving dots from you to the target on the world map and the minimap, along the travel route, while route lines are off."] = "Des points en mouvement de vous jusqu'à la cible sur la carte et la minicarte, le long de l'itinéraire, quand les lignes d'itinéraire sont désactivées."
L["Rares and treasures"] = "Rares et trésors"
L["Quest information, rewards and gear advice, and the quest buttons."] = "Infos de quête, récompenses, conseils d'équipement et boutons de quête."
L["Talents"] = "Talents"
L["Talent plan"] = "Plan de talents"
L["Lookup, the dungeon journal and rares: finding things in the world."] = "Recherche, journal des donjons et rares : trouver des choses dans le monde."
L["When a rare shows up"] = "Quand un rare apparaît"
L["How rares are noticed"] = "Détection des rares"
L["Status"] = "État"
L["Actions"] = "Actions"
L["Start recording"] = "Démarrer l'enregistrement"
L["Write quests, routes and world data for guide authors. Off until you start it."] = "Enregistre quêtes, trajets et données du monde pour les auteurs de guides. Inactif jusqu'au démarrage."
L["Print status"] = "Afficher l'état"
L["The Polestar Recorder addon is not loaded. Enable it in the AddOns list on the character screen to record your play for guide authoring."] = "L'addon Polestar Recorder n'est pas chargé. Activez-le dans la liste des addons de l'écran des personnages pour enregistrer votre partie pour écrire des guides."
L["Recording"] = "Enregistrement"
L["Stop recording"] = "Arrêter l'enregistrement"
L["Nothing more is written until you start it again."] = "Plus rien n'est enregistré jusqu'au prochain démarrage."
L["Leveling guides for World of Warcraft: Forever."] = "Guides de montée en niveau pour World of Warcraft: Forever."
L["Why Polestar"] = "Pourquoi Polestar"
L["Leveling guides have become a business: the best routes sit behind subscriptions and paywalls. Polestar goes the other way. It is free, open source under the GPL-3.0, and built by the community that plays it."] = "Les guides de montée en niveau sont devenus un business : les meilleurs itinéraires sont derrière des abonnements et des paywalls. Polestar prend le chemin inverse. Il est gratuit, open source sous GPL-3.0, et construit par la communauté qui y joue."
L["Polestar doesn't claim to be the fastest guide, or the smoothest. It is a free alternative, and it gets better with time."] = "Polestar ne prétend pas être le guide le plus rapide ni le plus fluide. C'est une alternative gratuite, qui s'améliore avec le temps."
L["Anyone can read the code, fix a step, sharpen a route or write a new guide, and contributions are welcome. The GPL keeps it that way: every copy and every fork stays open."] = "Tout le monde peut lire le code, corriger une étape, affiner un itinéraire ou écrire un nouveau guide, et les contributions sont bienvenues. La GPL le garantit : chaque copie et chaque fork reste ouvert."
L["It is young and still in beta, so expect the odd wrong step, waypoint or quest. Every report and every fix tunes it, and together we'll get it where it should be."] = "Il est jeune et encore en bêta : attendez-vous à quelques étapes, points de passage ou quêtes erronés. Chaque rapport et chaque correction l'améliorent, et ensemble nous l'amènerons là où il doit être."
L["Open source and free is the future."] = "L'open source et le gratuit sont l'avenir."
L["show or hide the guide window"] = "afficher ou masquer la fenêtre du guide"
L["choose a guide"] = "choisir un guide"
L["move through steps"] = "parcourir les étapes"
L["report a problem with a step on the Polestar Discord"] = "signaler un problème d'étape sur le Discord de Polestar"
L["every command"] = "toutes les commandes"
L["Credits"] = "Crédits"
L["Inter typeface by The Inter Project Authors, SIL Open Font License 1.1."] = "Police Inter par The Inter Project Authors, SIL Open Font License 1.1."
L["Wordmark set in Cinzel by The Cinzel Project Authors, SIL Open Font License 1.1."] = "Logotype en Cinzel par The Cinzel Project Authors, SIL Open Font License 1.1."
L["Quest and map data includes pfQuest by shagu (MIT License)."] = "Les données de quêtes et de carte incluent pfQuest par shagu (licence MIT)."
L["Discord and its logo are trademarks of Discord Inc.; the logo marks the link to the Polestar Discord."] = "Discord et son logo sont des marques de Discord Inc. ; le logo signale le lien vers le Discord de Polestar."
L["With EllesmereUI installed, Polestar can follow its accent, font and panel colour through its public skinning API."] = "Avec EllesmereUI installé, Polestar peut suivre son accent, sa police et sa couleur de panneau via son API publique d'habillage."
L["Maintenance"] = "Maintenance"
L["Reset all settings"] = "Réinitialiser tous les réglages"
L["Every Polestar setting back to default. Progress is kept."] = "Tous les réglages de Polestar par défaut. La progression est conservée."
L["Reset positions"] = "Réinitialiser les positions"
L["Guide window, arrow and these windows."] = "Fenêtre du guide, flèche et ces fenêtres."
L["Guides made by other players: switch them on or off, and choose where suggestions come from."] = "Guides créés par d'autres joueurs : activez-les ou désactivez-les, et choisissez la source des suggestions."
L["The data recorder for guide authors."] = "L'enregistreur de données pour les auteurs de guides."
L["Why Polestar exists, its commands and its credits."] = "Pourquoi Polestar existe, ses commandes et ses crédits."
L["Nothing to set here yet: the module behind this page is not loaded."] = "Rien à régler ici pour l'instant : le module de cette page n'est pas chargé."
L["No settings match “%s”."] = "Aucun réglage ne correspond à « %s »."
L["1 setting matches"] = "1 réglage correspond"
L["%d settings match"] = "%d réglages correspondent"
L["Reset page"] = "Réinitialiser la page"
L["Reload UI"] = "Recharger l'interface"
L["Search settings"] = "Chercher un réglage"
L["Open Polestar settings"] = "Ouvrir les réglages de Polestar"
L["Close the game menu to see Polestar's settings (it cannot be closed for you in combat)."] = "Fermez le menu du jeu pour voir les réglages de Polestar (il ne peut pas être fermé pour vous en combat)."
L["This translation was made with AI. Help improve it on Discord."] = "Cette traduction a été faite par une IA. Aidez à l'améliorer sur Discord."
L["Close the game menu to see Polestar's settings."] = "Fermez le menu du jeu pour voir les réglages de Polestar."
L["Integrations"] = "Intégrations"
L["Settings for other addons Polestar works with, shown when they are installed."] = "Réglages des autres addons avec lesquels Polestar fonctionne, affichés quand ils sont installés."
L["None of the addons Polestar works with is installed."] = "Aucun des addons avec lesquels Polestar fonctionne n'est installé."
L["The skin's font (the default: the game's own, Fira Sans in Halo), or a font of your choice."] = "La police de l'habillage (par défaut : celle du jeu, Fira Sans dans Halo) ou une police de votre choix."
L["The skin's font"] = "La police de l'habillage"
L["Skin"] = "Habillage"
L["The skin's arrow"] = "La flèche de l'habillage"
L["Lock arrow and buttons"] = "Verrouiller flèche et boutons"
L["Stops stray drags on the arrow, the action buttons and the flight and instance timers. Shift-drag still moves them."] = "Empêche les déplacements involontaires de la flèche, des boutons d'action et des minuteurs de vol et d'instance. Maj-glisser les déplace toujours."
L["Line style"] = "Style de ligne"
L["Bar at the bottom"] = "Barre en bas"
L["With Grow upward, put the tabs and the step bar at the bottom edge, next to where the window is pinned."] = "Avec « Agrandir vers le haut », place les onglets et la barre d'étape sur le bord inférieur, près de l'ancrage de la fenêtre."
L["Close offers the guide skips"] = "Fermer les propositions ignorées par le guide"
L["After Polestar accepts or turns in a quest, closes the quest window the NPC opens next when the guide skips its quests. Hold Shift to keep it open."] = "Quand Polestar accepte ou rend une quête, ferme la fenêtre de quête que le PNJ ouvre ensuite si le guide ignore ses quêtes. Maintenez Maj pour la garder ouverte."
L["Elite and escort quests the guides mark for a group. Ask at each, or answer them all: with a group (a party levelling together) or skip them (solo). Discovery, Group quests changes one."] = "Les quêtes élites et d'escorte que les guides réservent à un groupe. Demander à chaque fois, ou répondre pour toutes : en groupe (un groupe qui monte de niveau ensemble) ou les passer (en solo). Découverte, Quêtes de groupe en change une."
L["Ask me at each"] = "Me demander à chaque fois"
L["Do them with a group"] = "Les faire en groupe"
L["Skip them"] = "Les passer"
L["Offer class quests"] = "Proposer les quêtes de classe"
L["When one of your class's Class guides opens (your level, its first quest), the guide window offers to open it in a tab."] = "Quand l'un des guides de classe de votre classe devient disponible (votre niveau, sa première quête), la fenêtre du guide propose de l'ouvrir dans un onglet."
L["Celebrating the supporters, contributors and bug reporters behind Polestar."] = "Hommage aux soutiens, contributeurs et signaleurs de bugs de Polestar."
L["Position trails, marks and the list of spots to walk, in a small window."] = "Traces de position, repères et liste des lieux à parcourir, dans une petite fenêtre."
L["Reset guide progress?"] = "Réinitialiser la progression du guide ?"
L["Reset progress"] = "Réinitialiser la progression"
L["Reset all settings?"] = "Réinitialiser tous les réglages ?"
L["Reset all"] = "Tout réinitialiser"
L["Every Polestar setting goes back to its default. Your guides and progress are kept."] = "Chaque réglage de Polestar revient à sa valeur par défaut. Vos guides et votre progression sont conservés."
L["Preview"] = "Aperçu"
L["Live"] = "En direct"
L["Rot Hide Mongrel"] = "Bâtard Peau-pourrie"
L["Brill"] = "Brill"
L["Run"] = "Lancer"
L["Reset this page?"] = "Réinitialiser cette page ?"
L["Every setting on %s goes back to its default."] = "Chaque réglage de %s revient à sa valeur par défaut."
L["Waiting to upload"] = "En attente d'envoi"
L["Chunks the Polestar Uploader has not sent yet."] = "Blocs que Polestar Uploader n'a pas encore envoyés."
L["Stored"] = "Stockés"
L["Last uploaded chunk"] = "Dernier bloc envoyé"
L["Recordings"] = "Enregistrements"
L["Chunks waiting, the last upload and the install id, in chat."] = "Blocs en attente, dernier envoi et identifiant d'installation, dans le chat."
L["Characters"] = "Personnages"
L["Icon pack"] = "Jeu d'icônes"
L["The medallion under every mark on the world map and the minimap. The skin's: Polestar's, Halo's, or Hearth's for Hearth and the game's own looks. Glyphs only: no medallion."] = "Le médaillon sous chaque marque sur la carte et la minicarte. Celui de l'habillage : celui de Polestar, de Halo, ou de Foyer pour Foyer et les apparences du jeu. Glyphes seuls : pas de médaillon."
L["The skin's icons"] = "Les icônes de l'habillage"
L["Glyphs only"] = "Glyphes seuls"
L["Use deathskips"] = "Mourir pour gagner du temps"
L["Where dying on purpose and taking the Spirit Healer's resurrection gets you there sooner, the guide shows a step for it. It costs durability and, from level 11, resurrection sickness. Always off on Hardcore characters."] = "Là où mourir exprès et ressusciter auprès de l'esprit guérisseur vous y mène plus vite, le guide affiche une étape pour cela. Cela coûte de la durabilité et, à partir du niveau 11, du mal de résurrection. Toujours désactivé sur les personnages Hardcore."
L["Text size"] = "Taille du texte"
L["The size of Polestar's text, apart from the window scale. Changes at once. Right-click to reset."] = "La taille du texte de Polestar, indépendamment de l'échelle de la fenêtre. S'applique aussitôt. Clic droit pour réinitialiser."
L["Numbered pins for the steps ahead"] = "Repères numérotés des étapes à venir"
L["A small pin with its step number where each of the next steps takes you, fainter the further ahead. As many as Up next shows, else five."] = "Un petit repère avec son numéro d'étape là où chacune des étapes suivantes vous mène, plus pâle à mesure qu'elle est lointaine. Autant que À suivre en affiche, sinon cinq."
L["%d KiB"] = "%d Kio"
L["%.1f MB"] = "%.1f Mo"
L["%d KB"] = "%d Ko"
L["When a leveling guide ends"] = "À la fin d'un guide de progression"
L["Ask me: a window says the guide is done and offers the next one. Continue automatically: the next guide loads in the same tab."] = "Me demander : une fenêtre indique que le guide est terminé et propose le suivant. Continuer automatiquement : le guide suivant se charge dans le même onglet."
L["Ask me"] = "Me demander"
L["Continue automatically"] = "Continuer automatiquement"
L["Show the whole step"] = "Afficher toute l'étape"
L["Every goal of the step at once, finished ones kept, instead of one person at a time with the others on one line each."] = "Tous les objectifs de l'étape d'un coup, ceux terminés compris, au lieu d'une personne à la fois avec les autres sur une ligne chacune."
L["Maximum height"] = "Hauteur maximale"
L["How tall the window may grow, as a share of the screen. A longer step scrolls."] = "Jusqu'où la fenêtre peut grandir, en part de l'écran. Une étape plus longue défile."
L["Hide the arrow with the guide"] = "Masquer la flèche avec le guide"
L["When the guide window is hidden, hide the arrow too."] = "Quand la fenêtre du guide est masquée, masquer aussi la flèche."
L["Small conveniences: questing, travel, invitations, merchants, bags, trackers and the map."] = "Petites commodités : quêtes, voyages, invitations, marchands, sacs, suivis et la carte."
L["Did you mean:"] = "Vouliez-vous dire :"
L["In dungeons and battlegrounds"] = "Dans les donjons et champs de bataille"
L["How close"] = "Distance"
L["Include nearby hand-ins"] = "Inclure les quêtes à rendre proches"
L["Wait for Spoken"] = "Attendre Spoken"
L["Waits 200 ms before each automatic quest accept, turn-in and reward pick, so Spoken has time to notice the window and read it."] = "Attend 200 ms avant chaque acceptation, rendu de quête et choix de récompense automatiques, pour que Spoken ait le temps de remarquer la fenêtre et de la lire."
L["Dynamic Questing"] = "Quêtes dynamiques"
L["Sound for a new suggestion"] = "Son pour une nouvelle suggestion"
L["Suggests objectives from later steps when you are near them, from your quest log and what is around you. They show under the step in a \"While you're here\" panel: click one to point the arrow there; right-click to dismiss it around here (dismissed twice, it stays away for the zone)."] = "Suggère des objectifs d'étapes ultérieures quand vous en êtes proche, d'après votre journal des quêtes et ce qui vous entoure. Ils s'affichent sous l'étape dans un panneau « Tant que vous êtes là » : cliquez sur l'un pour y diriger la flèche ; clic droit pour l'écarter dans ce secteur (écarté deux fois, il disparaît pour la zone)."
L["A soft chime for each new suggestion (once when several come together), at the game's sound effects volume."] = "Un léger carillon pour chaque nouvelle suggestion (une seule fois quand plusieurs arrivent ensemble), au volume des effets sonores du jeu."
L["What's new"] = "Nouveautés"
L["When you abandon a guide quest"] = "Quand vous abandonnez une quête du guide"
L["Always go back for it"] = "Toujours y retourner"
L["Always skip it"] = "Toujours la passer"
L["Ask me: the guide stays on its step, leads you back to the quest giver, and the guide window asks. Or always go back for the quest, or always skip it and the quests that follow from it; chat says which."] = "Me demander : le guide reste sur son étape, vous ramène au donneur de quête, et la fenêtre du guide vous demande. Ou toujours retourner chercher la quête, ou toujours la passer avec les quêtes qui en découlent ; le chat indique lequel."
L["Also a quest ready to hand in whose NPC is a little out of your way, when the guide hands it in later."] = "Aussi une quête prête à rendre dont le PNJ est un peu à l'écart de votre chemin, quand le guide la rend plus tard."
L["Hand-ins: how far out of your way"] = "Quêtes à rendre : détour maximal"
L["The seconds of extra walking a hand-in may cost, to its NPC and back on your way. One in the town you are in always shows; 0 keeps to those."] = "Les secondes de marche en plus qu'une quête à rendre peut coûter, jusqu'à son PNJ et retour sur votre chemin. Une quête dans la ville où vous êtes s'affiche toujours ; 0 s'en tient à celles-là."
L["Route line on the minimap"] = "Ligne d'itinéraire sur la minicarte"
L["The way to the goal on the minimap. Off keeps the guide pin there and the line on the world map. Its colour, opacity and size: the gear beside Guide > Arrow & routes > Route lines."] = "Le chemin vers l'objectif sur la minicarte. Désactivé, l'épingle du guide reste sur la minicarte et la ligne sur la carte du monde. Sa couleur, son opacité et sa taille : l'engrenage à côté de Guide > Flèche et itinéraires > Lignes d'itinéraire."
L["Show and hide"] = "Afficher et masquer"
L["Floating button"] = "Bouton flottant"
L["Step key targets their mobs"] = "La touche d'étape cible leurs monstres"
L["The step key also targets the mobs of the suggestions, nearest first, after the current step's own. It changes only out of combat."] = "La touche d'étape cible aussi les monstres des suggestions, le plus proche d'abord, après ceux de l'étape actuelle. Elle ne change que hors combat."
L["Mark quests new in Forever"] = "Marquer les quêtes nouvelles dans Forever"
L["A small infinity mark beside the name of a quest Forever added, in the guide, While you're here, the Codex and quest tooltips."] = "Un petit symbole infini à côté du nom d'une quête ajoutée par Forever, dans le guide, « Tant que vous êtes là », le Codex et les infobulles de quête."
L["The way to the goal on the world map and the minimap: a line or dots where you walk, lines where you fly, sail or ride, the legs after this one fainter. Drawn as Shortest Path Forever by Cillian Berragan draws them."] = "Le chemin vers l'objectif sur la carte du monde et la minicarte : une ligne ou des points là où vous marchez, des lignes là où vous volez, naviguez ou voyagez, les tronçons suivants plus pâles. Dessiné comme le fait Shortest Path Forever par Cillian Berragan."
L["How the route lines are drawn: one solid line, Polestar's dots, or sparkles that drift along the way to the goal (dots while Reduce motion is on)."] = "Comment les lignes d'itinéraire sont tracées : une ligne continue, les points de Polestar, ou des étincelles qui dérivent le long du chemin vers l'objectif (des points quand Réduire les animations est activé)."
L["A Polestar button in the game menu (Esc) that opens the guide menu."] = "Un bouton Polestar dans le menu du jeu (Échap) qui ouvre le menu du guide."
L["Backing"] = "Fond"
L["Soft"] = "Léger"
L["Dark"] = "Sombre"
L["With Transparent, the tabs and the step bar stay on screen instead of only under the cursor."] = "Avec Transparent, les onglets et la barre d'étape restent à l'écran au lieu d'apparaître seulement sous le curseur."
L["With Transparent: Soft lays a light shade behind each line of text, Dark a dark backing behind the whole window. Off: the outlined text alone on the world."] = "En Transparent : Léger place une ombre légère derrière chaque ligne de texte, Sombre un fond sombre derrière toute la fenêtre. Désactivé : le texte détouré seul sur le monde."
L["Tell me when a newer Polestar is out"] = "Me prévenir quand un Polestar plus récent sort"
L["At login, a card on the guide window says a newer Polestar is out and how to update; Got it keeps it away for a day. A line in the guide window stays until you update. Two or more updates behind, both show even with this off (the card at most once a day)."] = "À la connexion, une carte sur la fenêtre du guide indique qu'un Polestar plus récent est sorti et comment mettre à jour ; « Compris » l'écarte pour une journée. Une ligne dans la fenêtre du guide reste jusqu'à la mise à jour. À partir de deux mises à jour de retard, les deux s'affichent même si cette option est désactivée (la carte au plus une fois par jour)."
L["What the window, its buttons and alerts do in dungeons, raids, battlegrounds and arenas. Guide window in the minimap button's menu, the key binding or /polestar opens it there until you leave."] = "Ce que font la fenêtre, ses boutons et ses alertes dans les donjons, raids, champs de bataille et arènes. « Fenêtre du guide » dans le menu du bouton de la minicarte, le raccourci clavier ou /polestar l'y ouvre jusqu'à ce que vous en sortiez."
L["A small Polestar button you can put anywhere on the screen. Click to hide or show Polestar, right-click for a menu, drag to move it. It hides with the window in combat and in dungeons when those are set to Hide."] = "Un petit bouton Polestar que vous pouvez placer n'importe où sur l'écran. Cliquez pour masquer ou afficher Polestar, clic droit pour un menu, faites-le glisser pour le déplacer. Il se masque avec la fenêtre en combat et dans les donjons quand ceux-ci sont réglés sur Masquer."
L["Hiding Polestar leaves the arrow, its travel button and its arrival sound. This character only."] = "Masquer Polestar laisse la flèche, son bouton de voyage et le son d'arrivée. Pour ce personnage seulement."
L["How near the middle of its spawn area you must be for a suggestion to show. It goes again a little further out."] = "À quelle distance du centre de sa zone d'apparition vous devez être pour qu'une suggestion s'affiche. Elle disparaît un peu plus loin."
L["Flight paths you pass"] = "Trajet aérien sur votre chemin"
L["Also a friendly flight master near you whose flight path you haven't learned yet. Learning it ticks the guide's later step for it too."] = "Aussi un maître de vol amical près de vous dont vous n'avez pas encore appris le trajet aérien. L'apprendre coche aussi l'étape prévue plus tard pour lui dans le guide."
L["Detour captions"] = "Légendes de contournement"
L["Under a walk in the journey, say when it goes round a town of the other faction: \"Detour around Southshore\". It only says so: the route and the arrow stay as they are."] = "Sous une marche du trajet, indique quand elle contourne une ville de l'autre faction : « Contourne Austrivage ». Ce n'est qu'une indication : l'itinéraire et la flèche restent les mêmes."
L["Manual check-offs and skips, current guide, from your last quest progress on."] = "Coches manuelles et étapes passées, guide actuel, à partir de votre dernière progression de quête."
L["Your manual check-offs and skipped steps in %s are cleared from your last quest progress on. Quests you have done stay done, and the guide stays where they put you."] = "Vos cases cochées et étapes passées dans %s sont effacées à partir de votre dernière progression de quête. Les quêtes faites restent faites, et le guide reste là où elles vous ont mené."
L["Your manual check-offs and skipped steps in the current guide are cleared from your last quest progress on. Quests you have done stay done, and the guide stays where they put you."] = "Vos cases cochées et étapes passées dans le guide actuel sont effacées à partir de votre dernière progression de quête. Les quêtes faites restent faites, et le guide reste là où elles vous ont mené."
