L["The guide"] = "Le guide"
L["Quest buttons"] = "Boutons de quête"
L["The guide window holds the gamepad until B: the D-pad picks a line, A points the arrow there or uses the item, X shows its details, LB and RB change steps, Y minimizes the window. A window that opened by itself, such as a route choice, waits for this button before it takes the gamepad."] = "La fenêtre du guide garde la manette jusqu'à B : la croix choisit une ligne, A y pointe la flèche ou utilise l'objet, X affiche ses détails, LB et RB changent d'étape, Y réduit la fenêtre. Une fenêtre ouverte d'elle-même, comme un choix d'itinéraire, attend ce bouton avant de prendre la manette."
L["Browsing the guide needs the game's gamepad interface (Options, Gamepad, Enable Gamepad UI), or Use with the keyboard and mouse on Polestar's Gamepad page with a gamepad plugged in."] = "Pour parcourir le guide, il faut l’interface manette du jeu (options du jeu, Manette) ou « Utiliser avec le clavier et la souris » sur la page Manette de Polestar, avec une manette branchée."
L["Use with the keyboard and mouse"] = "Utiliser avec le clavier et la souris"
L["Off, Polestar uses the gamepad only with the game's gamepad interface (Options, Gamepad, Enable Gamepad UI). On, also with the keyboard and mouse interface, while the gamepad is turned on in the game's options and plugged in."] = "Désactivé : Polestar n’utilise la manette qu’avec l’interface manette du jeu (options du jeu, Manette). Activé : aussi avec l’interface clavier et souris, tant que la manette est activée dans les options du jeu et branchée."

-- Core/RoutePlan.lua
L["step %d"] = "étape %d"
L["%s · %s"] = "%s · %s"
L["Turn in at this step · %s"] = "Rendre à cette étape · %s"
L["Turn in at %s"] = "Rendre à %s"
L["Earlier turn-in · %s — check"] = "Rendu antérieur · %s — à vérifier"
L["Skipped turn-in · %s — check"] = "Rendu passé · %s — à vérifier"
L["Turn-in plan depends on your next route choice"] = "Le plan de rendu dépend de votre prochain choix d'itinéraire"
L["Next guide is not loaded; turn-in plan unavailable"] = "Le guide suivant n'est pas chargé ; plan de rendu indisponible"
L["No turn-in in this route"] = "Aucun rendu sur cet itinéraire"
L["Select a guide to see its turn-in plan"] = "Sélectionnez un guide pour voir son plan de rendu"
L["%s (optional)"] = "%s (facultatif)"

-- UI/QuestieTurnIns.lua
L["Polestar: %s"] = "Polestar : %s"
L["Show planned turn-ins in Questie"] = "Afficher les rendus prévus dans Questie"
L["Completed quests in Questie's tracker show their Polestar turn-in step. Earlier, skipped and unplanned hand-ins are flagged."] = "Les quêtes terminées dans le suivi de Questie affichent leur étape de rendu Polestar. Les rendus antérieurs, passés et non prévus sont signalés."

-- Talents/Builds.lua
L["Holy"] = "Sacré"
L["Protection"] = "Protection"
L["Level as Retribution (quickest solo, with a two-hander and Seal of Command) or Protection (safe group pulls, dungeon-tank ready). Holy suits raids; it can level through its melee build, more slowly, if you want to heal dungeons on the way."] = "Montez de niveau en Vindicte (le plus rapide en solo, avec une arme à deux mains et Sceau d'autorité) ou en Protection (pulls de groupe sûrs, prêt à tanker les donjons). Sacré convient aux raids ; il peut monter de niveau avec son build de mêlée, plus lentement, si vous voulez soigner des donjons en chemin."
L["Start with Divine Intellect: more mana means you can melee and still cover your own (or a group's) healing."] = "Commencez par Intelligence divine : plus de mana vous permet de combattre en mêlée tout en assurant vos propres soins (ou ceux d'un groupe)."
L["Improved Seals raises every seal and Judgement here, which is where Holy's leveling damage comes from."] = "Sceaux améliorés renforce ici chaque sceau et Jugement : c'est de là que viennent les dégâts de Sacré en montée de niveau."
L["Reverence keeps a trickle of regen going while casting; three ranks unlock Illumination."] = "Révérence maintient un filet de régénération pendant les incantations ; trois rangs débloquent Illumination."
L["Illumination refunds mana on critical heals and is the heart of Holy's staying power."] = "Illumination rend du mana sur les soins critiques et est au cœur de l'endurance de Sacré."
L["Holy Shock is a talent on Forever: an instant heal or Holy hit, handy for emergencies and for pulling."] = "Horion sacré est un talent sur Forever : un soin ou un coup Sacré instantané, utile en urgence et pour puller."
L["Holy Power raises Holy Shock's crit chance, feeding Illumination and Infusion of Light."] = "Puissance sacrée augmente les chances de critique d'Horion sacré, ce qui alimente Illumination et Imprégnation de lumière."
L["Light's Vigil turns Holy Shock into a group-heal burst; this is the signature Forever Holy talent."] = "Veille de la Lumière transforme Horion sacré en salve de soins de groupe ; c'est le talent Sacré emblématique de Forever."
L["The remaining 20 points go to Retribution: cheaper spells and more melee crit while questing, ending in Seal of Command."] = "Les 20 points restants vont en Vindicte : sorts moins chers et plus de critiques en mêlée en quêtant, jusqu'à Sceau d'autorité."
L["Open with Redoubt: blocking pays off at once, and Shield Specialization needs all five ranks."] = "Commencez par Redoute : le blocage est rentable tout de suite, et Spécialisation Bouclier demande les cinq rangs."
L["Precision and Anticipation help you land hits and dodge them while questing with a shield."] = "Précision et Anticipation vous aident à toucher et à esquiver en quêtant avec un bouclier."
L["Improved Seal of Fury and Improved Righteous Fury begin the mana and mitigation cycle Forever tanking is built on."] = "Sceau de fureur amélioré et Fureur vertueuse améliorée lancent le cycle de mana et d'atténuation sur lequel repose le tanking sur Forever."
L["Around 20 points in, you match the usual dungeon-tank setup: Shield Specialization, Sacred Duty and Swift Judgement are complete."] = "Vers 20 points, vous avez la configuration habituelle de tank de donjon : Spécialisation Bouclier, Devoir sacré et Jugement rapide sont complets."
L["Templar's Bulwark is an absorb cooldown that scales with your health, and Holy Shield later in the plan requires it."] = "Rempart du templier est un temps de recharge d'absorption qui évolue avec vos points de vie, et Bouclier sacré l'exige plus loin dans le plan."
L["Iron Creed adds threat and damage reduction to Holy Strike while Righteous Fury is active."] = "Credo de fer ajoute de la menace et une réduction des dégâts à Frappe sacrée tant que Fureur vertueuse est active."
L["Holy Shield is the capstone: more block uptime, with Holy damage each time you block. Ideal for pulling packs."] = "Bouclier sacré est l'aboutissement : plus de temps de blocage, avec des dégâts Sacré à chaque blocage. Idéal pour puller des groupes."
L["Leftover points buy armor, a quicker Hammer of Justice, and Holy Strength and seal damage for leveling."] = "Les points restants achètent de l'armure, un Marteau de la justice plus rapide, ainsi que Force sacrée et des dégâts de sceau pour la montée de niveau."
L["Benediction lowers the mana cost of Judgement, Holy Strike and seals, so you rest less between fights."] = "Bénédiction réduit le coût en mana de Jugement, Frappe sacrée et des sceaux : vous vous reposez moins entre les combats."
L["Seal of Command is the main two-hander seal for leveling; take it as soon as it opens."] = "Sceau d'autorité est le sceau principal à deux mains pour monter de niveau ; prenez-le dès qu'il est disponible."
L["Sanctified Judgement gives mana back and is the prerequisite arrow for Vengeance."] = "Jugement sanctifié rend du mana et est le prérequis (flèche) de Vengeance."
L["Sacred Arbiter strengthens Holy Strike and keeps Judgements rolling, and completes the 20 points row 5 asks for."] = "Arbitre sacré renforce Frappe sacrée, fait tourner les Jugements et complète les 20 points exigés par la rangée 5."
L["Vengeance, then Two-Handed Weapon Specialization: the crit-driven damage core of the two-hander plan."] = "Vengeance, puis Spécialisation Arme à deux mains : le cœur des dégâts critiques du plan à deux mains."
L["Pursuit of Justice adds run speed. Champion of the Light is left out while the Retribution Aura spell-power bug keeps spell damage low."] = "Poursuite de la justice augmente la vitesse de course. Champion de la Lumière est laissé de côté tant que le bug de puissance des sorts d'Aura de vindicte maintient les dégâts des sorts bas."
L["Twist of Light makes swapping seals cheaper and adds seal echoes; it is Forever's seal-twisting talent."] = "Torsion de Lumière rend le changement de sceau moins cher et ajoute des échos de sceau ; c'est le talent d'alternance de sceaux de Forever."
L["Spare points go to Divine Strength and Holy's Improved Seals for damage, then Deflection for survival."] = "Les points en trop vont à Force divine et aux Sceaux améliorés de Sacré pour les dégâts, puis à Déviation pour la survie."
L["Level as Combat with a sword (Riposte, Blade Flurry, Adrenaline Rush) for the steadiest kills, or Assassination with daggers and poisons (Mutilate). Subtlety's Hemorrhage plan suits stealth openers and is slower solo."] = "Montez en niveau en Combat avec une épée (Riposte, Tourbillon de lames, Ruée d'adrénaline) pour des kills réguliers, ou en Assassinat avec des dagues et des poisons (Mutilation). Le plan Hémorragie de Subtilité convient aux ouvertures en furtivité et est plus lent en solo."
L["Malice first: crit for every attack and poison, and it opens Lethality."] = "Malveillance en premier : critique pour chaque attaque et chaque poison, et ouvre Léthalité."
L["Ruthlessness gives finishers a chance at a free combo point; Murder adds damage against humanoids and giants."] = "La Cruauté donne aux finisseurs une chance d'obtenir un point de combo gratuit; Meurtre ajoute des dégâts contre les humanoïdes et les géants."
L["Relentless Strikes refunds energy from finishers, so fights flow without waiting."] = "Les Coups implacables remboursent de l'énergie sur les finisseurs, les combats s'enchaînent sans attendre."
L["Improved Poisons puts poisons on more often and makes charges last; take them as soon as you train poisons."] = "Poisons améliorés applique les poisons plus souvent et fait durer les charges; prenez-le dès que vous apprenez les poisons."
L["Mutilate is Forever's dual-wield dagger strike: two combo points a use, and more damage on poisoned targets."] = "Mutilation est la frappe de dague en double arme de Forever : deux points de combo par utilisation et plus de dégâts sur les cibles empoisonnées."
L["Seal Fate turns crits into extra combo points; with Malice and Lethality it is the core of the build."] = "Sceau du destin convertit les coups critiques en points de combo supplémentaires ; avec Malveillance et Léthalité, c'est le cœur de la build."
L["Venom is the capstone: a finisher that strengthens your poisons for a while."] = "Venin est le capstone : un finisseur qui renforce vos poisons pendant un moment."
L["The last 20 points go to Combat: cheaper Sinister Strikes, a stronger Eviscerate, more hit and parry, Riposte and a stronger off-hand."] = "Les 20 derniers points vont en Combat : des Coups sournois moins chers, un Éviscération plus puissant, plus de toucher et de parade, Riposte et une main secondaire plus forte."
L["Improved Sinister Strike first: cheaper Sinister Strikes are the biggest early gain."] = "Coup sournois amélioré en premier : des Coups sournois moins chers sont le plus grand gain en début de partie."
L["Precision helps you hit more often; it also opens Dual Wield Specialization."] = "La Précision vous aide à toucher plus souvent ; elle ouvre aussi Spécialisation double arme."
L["Riposte follows each parry with a heavy strike that also disarms."] = "La Riposte suit chaque parade d'un coup puissant qui désarme également."
L["Blade Flurry is faster attacks and cleave on demand; Hack and Slash then adds extra attacks with swords and axes."] = "Le Tourbillon de lames accélère les attaques et offre un coup en éventail à la demande ; Hacher et trancher ajoute ensuite des attaques supplémentaires avec des épées et des haches."
L["Adrenaline Rush is the capstone: double energy for 15 seconds, enough for a second mob."] = "La Ruée d'adrénaline est le capstone : double énergie pendant 15 secondes, suffisant pour un deuxième mob."
L["The remaining points go to Assassination for crit, free combo points, energy refunds and Lethality."] = "Les points restants vont en Assassinat pour les critiques, les points de combo gratuits, les remboursements d'énergie et Léthalité."
L["Opportunity adds damage to Backstab, Ambush and Garrote, your stealth openers."] = "L'Opportunité ajoute des dégâts au Coup dans le dos, à l'Embuscade et à l'Étranglement, vos ouvertures en furtivité."
L["Improved Ambush and Initiative make the opener the fight: a likely crit and extra combo points."] = "Embuscade améliorée et Initiative font de l'ouverture le combat : un probable critique et des points de combo supplémentaires."
L["Serrated Blades ignores armor and is the way into Hemorrhage."] = "Lames dentelées ignore l'armure et ouvre la voie vers Hémorragie."
L["Hemorrhage is your main builder from here, with any weapon, and it adds to Rupture damage."] = "Hémorragie est votre principal générateur à partir d'ici, avec n'importe quelle arme, et ajoute aux dégâts de Rupture."
L["Quietus adds damage to Hemorrhage and Ghostly Strike on a low-health target, finishing mobs sooner."] = "Quiétude ajoute des dégâts à Hémorragie et Frappe spectrale sur une cible à faible santé, éliminant les monstres plus vite."
L["Thousand Cuts is the capstone: Rupture ticks make your next Hemorrhage cheaper."] = "Mille coupures est le capstone : les pulsations de Rupture rendent votre prochaine Hémorragie moins chère."
L["Level as Arms with a two-hander (Mortal Strike, Sweeping Strikes) or Fury (Enrage, Death Wish, then Flurry and Bloodthirst with two weapons). Protection is slower alone but ready to tank any dungeon on the way."] = "Montez en niveau en Armes avec une arme à deux mains (Coup mortel, Coups balayants) ou en Furie (Enrager, Soif de mort, puis Tornade et Soif de sang avec deux armes). Protection est plus lent seul mais prêt à tanker n'importe quel donjon en chemin."
L["Improved Heroic Strike first: Heroic Strike is your main rage dump, and a cheaper one means more of them."] = "Frappe héroïque améliorée en premier : Frappe héroïque est votre principal dépenseur de rage, et une moins chère en signifie davantage."
L["Improved Tactical Mastery keeps rage when you swap stances, so Charge, Overpower and Battle Stance openers cost you nothing."] = "La Maîtrise tactique améliorée conserve la rage lors des changements de posture, donc Charge, Écraser et les ouvertures en Posture de Combat ne coûtent rien."
L["Anger Management is a steady rage trickle in every fight; on Forever it also slows rage loss between pulls."] = "La Gestion de la colère est un flux régulier de rage dans chaque combat ; sur Forever, elle ralentit aussi la perte de rage entre les combats."
L["Improved Rend and Deep Wounds turn your crits into bleeds; Deep Wounds also opens Impale."] = "Lacération améliorée et Blessures profondes transforment vos coups critiques en saignements ; Blessures profondes ouvre aussi Empalage."
L["Sweeping Strikes makes two-mob pulls quick; Weaponmaster then adds crit, armor penetration or extra attacks for your weapon type."] = "Les Coups balayants rendent rapides les pulls de deux monstres ; Maître d'armes ajoute ensuite des critiques, une pénétration d'armure ou des attaques supplémentaires pour votre type d'arme."
L["Improved Slam stops Slam from resetting your swing: a free hit between big two-hander swings."] = "Frappe puissante améliorée empêche Frappe puissante de réinitialiser votre balancement : un coup gratuit entre les grands balayages à deux mains."
L["Mortal Strike is the capstone and your hardest-hitting strike for the rest of the climb."] = "Coup mortel est le capstone et votre frappe la plus puissante pour le reste de la montée."
L["The last 20 points go to Fury: Cruelty and Unbridled Wrath give more crit and more rage."] = "Les 20 derniers points vont en Furie : Cruauté et Fureur déchaînée donnent plus de critiques et plus de rage."
L["Enrage finishes the plan: a damage boost that is often up while you take hits."] = "Enrager termine le plan : un boost de dégâts souvent actif pendant que vous encaissez des coups."
L["Cruelty first: more crit for every build, and the way into the Fury tree."] = "Cruauté en premier : plus de critiques pour chaque build, et la voie dans l'arbre Furie."
L["Unbridled Wrath means more rage from every swing, which matters most with two fast weapons."] = "La Fureur déchaînée signifie plus de rage à chaque attaque, ce qui compte le plus avec deux armes rapides."
L["Piercing Howl stops runners and lets you walk away from a bad pull."] = "Le Rugissement perçant arrête les fuyards et vous permet de vous éloigner d'un mauvais pull."
L["Enrage raises your physical damage after you are hit, so it is often up while you take hits."] = "Enrager augmente vos dégâts physiques après avoir été touché, donc il est souvent actif pendant que vous encaissez des coups."
L["Death Wish is a big cooldown for elites and a fear breaker; it also opens Flurry."] = "Soif de mort est un grand temps de recharge pour les élites et brise la peur ; elle ouvre aussi Tornade."
L["Dual Wield Specialization: more off-hand damage and rage now that you carry two weapons."] = "Spécialisation double arme : plus de dégâts de main secondaire et de rage maintenant que vous portez deux armes."
L["Bloodthirst is the capstone: a strong instant attack and a little run speed between mobs."] = "Soif de sang est le capstone : une forte attaque instantanée et un peu de vitesse de déplacement entre les monstres."
L["Gore Drinker turns your rage cooldowns into self-healing, so you rest less."] = "Buveur de sang transforme vos temps de recharge de rage en autosoins, vous vous reposez donc moins."
L["Spare points go to Arms for cheaper Heroic Strikes, stance-swap rage, Anger Management and Deep Wounds."] = "Les points restants vont en Armes pour des Frappes héroïques moins chères, la rage lors des changements de posture, la Gestion de la colère et Blessures profondes."
L["Shield Specialization: more blocks, and on Forever each block also gives rage."] = "Spécialisation bouclier : plus de blocages, et sur Forever chaque blocage donne également de la rage."
L["Improved Revenge makes Revenge, which you can use after each block, a real damage hit."] = "Coup de riposte amélioré fait de Coup de riposte, que vous pouvez utiliser après chaque blocage, un vrai coup de dégâts."
L["Last Stand is your emergency cooldown when a pull goes wrong."] = "Dernier rempart est votre temps de recharge d'urgence quand un pull tourne mal."
L["Vanguard lets you Charge from Defensive Stance: no stance dance to open a pull."] = "Avant-garde vous permet de Charger depuis la Posture défensive : pas de danse de posture pour ouvrir un pull."
L["Concussion Blow is a stun on demand, for an interrupt or to reach a runner."] = "Coup de concussion est un étourdissement à la demande, pour une interruption ou pour atteindre un fuyard."
L["Bastion adds damage to everything you do with a shield on; it is what makes Protection level well."] = "Bastion ajoute des dégâts à tout ce que vous faites avec un bouclier ; c'est ce qui fait bien monter en niveau la Protection."
L["Shield Slam is the capstone: a big hit that grows with your block value, and high threat for dungeons."] = "Coup de bouclier est le capstone : un grand coup qui augmente avec votre valeur de blocage et une haute menace pour les donjons."
L["Defiance, Improved Thunder Clap and Improved Shield Wall round out the tank kit for dungeons."] = "Défi, Claquement de tonnerre amélioré et Mur de boucliers amélioré complètent le kit de tank pour les donjons."
L["The last 10 points go to Arms: cheaper Heroic Strikes and Improved Tactical Mastery for swaps to Battle Stance."] = "Les 10 derniers points vont en Armes : des Frappes héroïques moins chères et la Maîtrise tactique améliorée pour les changements en Posture de combat."
L["Level as Frost (the safest: slows, freezes and Ice Barrier) or Fire (more damage, with Pyroblast openers and Blast Wave). Arcane builds around Arcane Blast and Arcane Power and wants more mana between pulls."] = "Montez en niveau en Givre (le plus sûr : ralentissements, gels et Barrière de glace) ou en Feu (plus de dégâts, avec des ouvertures Pyroblaste et Vague de choc). Arcane se construit autour d'Explosion arcanique et Puissance des arcanes et nécessite plus de mana entre les combats."
L["Improved Channeling first: Arcane Missiles, and later Arcane Blast, keep going when a mob hits you."] = "Canalisation améliorée en premier : les Missiles arcaniques, et plus tard Explosion arcanique, continuent quand un monstre vous frappe."
L["Arcane Concentration gives free casts now and then, and opens Arcane Meditation."] = "La Concentration arcanique donne des sorts gratuits de temps en temps et ouvre la Méditation arcanique."
L["Arcane Blast is Forever's Arcane builder: each cast adds spell power for the next."] = "Explosion arcanique est le générateur Arcane de Forever : chaque incantation ajoute de la puissance de sort pour la suivante."
L["Missile Barrage: Arcane Blast, Arcane Wrath, Fireball and Frostbolt can make your next Arcane Missiles faster and cheaper."] = "Barrage de missiles : Explosion arcanique, Fureur arcanique, Boule de feu et Trait de givre peuvent rendre vos prochains Missiles arcaniques plus rapides et moins chers."
L["Arcane Meditation keeps mana coming back while you cast, so you drink less."] = "La Méditation arcanique maintient la régénération de mana pendant que vous lancez des sorts, vous buvez donc moins."
L["Arcane Wrath, opened by Arcane Blast, is a nuke that grows with your maximum mana. Its point does not count toward the Arcane tiers, so the plan spends 32 points in Arcane."] = "Fureur arcanique, ouverte par Explosion arcanique, est un sort de nuke qui augmente avec votre mana maximum. Son point ne compte pas pour les niveaux arcaniques, donc le plan dépense 32 points en Arcane."
L["Presence of Mind makes one spell instant: an opener, or a finisher on a runner."] = "Présence d'esprit rend un sort instantané : une ouverture, ou un finisseur sur un fuyard."
L["Arcane Power is the capstone: more damage for more mana, best with Presence of Mind on a tough target."] = "Puissance des arcanes est le capstone : plus de dégâts contre plus de mana, idéal avec Présence d'esprit sur une cible coriace."
L["The remaining 19 points go to Frost for a quicker Frostbolt, a shorter Frost Nova cooldown, longer slows and Ice Block."] = "Les 19 points restants vont en Givre pour un Trait de givre plus rapide, un temps de recharge plus court de Nova de givre, des ralentissements plus longs et Bloc de glace."
L["Improved Fireball first: a faster Fireball is more damage every fight."] = "Boule de feu améliorée en premier : une Boule de feu plus rapide signifie plus de dégâts à chaque combat."
L["Ignite adds burn damage to every Fire crit."] = "Inflammation ajoute des dégâts de brûlure à chaque critique de Feu."
L["Pyroblast is a big opener from range; cast it first, then Fireball."] = "Pyroblaste est un grand ouvreur à distance ; lancez-le en premier, puis Boule de feu."
L["Master of Elements gives mana back on crits, so you rest less."] = "Maître des éléments rend du mana sur les critiques, vous vous reposez donc moins."
L["Critical Mass and Blast Wave: more crits, and an area attack and daze for when two mobs reach you."] = "Masse critique et Vague de choc : plus de critiques, et une attaque de zone et un étourdissement quand deux monstres vous atteignent."
L["Fire Power raises your Fire damage for each of your Fire effects on the target: Ignite, Pyroblast's burn and the like."] = "Puissance du feu augmente vos dégâts de Feu pour chaque effet de Feu sur la cible : Inflammation, la brûlure de Pyroblaste et similaires."
L["Combustion is the capstone: a crit cooldown for elites and big pulls."] = "Combustion est le capstone : un temps de recharge de critique pour les élites et les gros pulls."
L["The last 20 points go to Arcane: a stronger wand for finishing mobs, then Arcane Concentration's free casts and Arcane Meditation's regen while casting."] = "Les 20 derniers points vont en Arcane : une baguette plus puissante pour finir les monstres, puis les sorts gratuits de Concentration arcanique et la régénération en incantation de Méditation arcanique."
L["Improved Frostbolt first: a faster Frostbolt is your main gain for the early levels."] = "Trait de givre amélioré en premier : un Trait de givre plus rapide est votre principal gain pour les premiers niveaux."
L["Ice Shards makes Frost crits hit much harder."] = "Éclats de glace font que les critiques de Givre frappent beaucoup plus fort."
L["Improved Frost Nova and Ice Block are your escapes: freeze, step back, keep casting."] = "Nova de givre améliorée et Bloc de glace sont vos évasions : geler, reculer, continuer à lancer."
L["Shatter adds a large crit chance against frozen targets: Frost Nova, then Frostbolt or Ice Lance."] = "Brisement ajoute une grande chance de critique contre les cibles gelées : Nova de givre, puis Trait de givre ou Lance de glace."
L["Ice Barrier is the capstone: an absorb shield that also stops pushback while you cast."] = "Barrière de glace est le capstone : un bouclier d'absorption qui arrête aussi la perturbation lors des incantations."
L["Level as Affliction (instant Corruption, Siphon Life, drains) or Demonology (a tougher Voidwalker, Soul Link) for the fewest deaths. Destruction hits hardest with Conflagrate and Incinerate but needs more rest."] = "Montez en niveau en Affliction (Corruption instantanée, Siphon de vie, drainages) ou en Démonologie (un Marcheur du Vide plus solide, Lien d'âme) pour le moins de morts. Destruction frappe le plus fort avec Déflagration et Incinération mais nécessite plus de repos."
L["Improved Corruption makes Corruption instant: the core of Affliction leveling."] = "Corruption améliorée rend Corruption instantanée : le cœur du leveling en Affliction."
L["Improved Drains and Soul Harvest make Drain Life a heal and Drain Soul a mana return on kills."] = "Drainages améliorés et Moisson des âmes font de Drain de vie une guérison et de Drain d'âme un retour de mana sur les kills."
L["Nightfall gives an instant Shadow Bolt now and then while your damage over time ticks."] = "Chute de la nuit donne un Éclair des ténèbres instantané de temps en temps pendant que vos effets de dégâts sur la durée déclenchent."
L["Siphon Life adds another self-heal over time to the rotation."] = "Siphon de vie ajoute une autre auto-guérison sur la durée à la rotation."
L["Shadow Mastery adds damage to every Shadow spell."] = "Maîtrise des ombres ajoute des dégâts à chaque sort d'Ombre."
L["Wrack is the capstone: a strong channel that raises the damage the target takes from your other Shadow damage-over-time effects by 10%."] = "Wrack est le capstone : une canalisation puissante qui augmente de 10% les dégâts que la cible subit de vos autres effets d'Ombre sur la durée."
L["The last 20 points go to Demonology: more Stamina, a tougher Voidwalker, quicker summons and Demonic Sacrifice."] = "Les 20 derniers points vont en Démonologie : plus d'Endurance, un Marcheur du Vide plus solide, des invocations plus rapides et Sacrifice démoniaque."
L["Demonic Embrace first: more Stamina means more Life Taps and fewer deaths."] = "Étreinte démoniaque en premier : plus d'Endurance signifie plus de Puisage de vie et moins de morts."
L["Improved Voidwalker makes your tank pet hold mobs better and shield you."] = "Marcheur du Vide amélioré fait que votre compagnon tank maintient mieux les monstres et vous protège."
L["Soul Link shares your damage with your pet: with a Voidwalker you rarely die."] = "Lien d'âme partage vos dégâts avec votre familier : avec un Marcheur du Vide, vous mourez rarement."
L["Demonic Pact is the capstone: you keep Demonic Sacrifice's effect when you summon another demon."] = "Pacte démoniaque est le capstone : vous conservez l'effet de Sacrifice démoniaque quand vous invoquez un autre démon."
L["The rest goes to Affliction: an instant Corruption, stronger drains and Life Tap, and Nightfall's free Shadow Bolts."] = "Le reste va en Affliction : une Corruption instantanée, des drainages et Puisage de vie plus forts, et les Éclairs des ténèbres gratuits de Chute de la nuit."
L["Bane first: faster Shadow Bolts and Immolates."] = "Malédiction en premier : des Éclairs des ténèbres et des Immolations plus rapides."
L["Ruin makes Destruction crits hit much harder."] = "Ruine fait frapper beaucoup plus fort les critiques de Destruction."
L["Conflagrate turns your Immolate into burst damage; open with Immolate, then Conflagrate."] = "Déflagration transforme votre Immolation en dégâts explosifs ; ouvrez avec Immolation, puis Déflagration."
L["Incinerate is the capstone: a strong Fire nuke, best on an Immolated target."] = "Incinération est le capstone : un puissant sort de Feu, idéal sur une cible Immolée."
L["Level as Feral Combat: Cat Form for quick kills, Bear Form for tough pulls, and no drinking. Balance kills from range with roots and Starfire; Restoration heals any dungeon and quests slowly with Wrath."] = "Montez en niveau en Farouche : Forme Félin pour des kills rapides, Forme Ours pour les pulls difficiles, sans boire. Équilibre tue à distance avec des racines et Feu stellaire ; Restauration soigne n'importe quel donjon et quête lentement avec Courroux."
L["Improved Wrath first: a faster, cheaper Wrath is most of your early damage."] = "Courroux amélioré en premier : un Courroux plus rapide et moins cher représente l'essentiel de vos dégâts précoces."
L["Moonglow and Nature's Majesty: cheaper spells and more crit."] = "Lueur de lune et Majesté de la nature : des sorts moins chers et plus de critiques."
L["Improved Entangling Roots holds a mob in place while you nuke it from range."] = "Racines enchevêtrées améliorées maintient un monstre en place pendant que vous le bombardez à distance."
L["Nature's Grace speeds up your next spell after a crit."] = "Grâce de la nature accélère votre prochain sort après un critique."
L["Moonkin Form is the capstone: armor and more free casts while you nuke."] = "Forme de Moonfurien est le capstone : armure et plus de sorts gratuits pendant que vous attaquez."
L["The last 20 points go to Restoration: fewer interrupted casts, Naturalist's damage, regen while casting and stronger heals."] = "Les 20 derniers points vont en Restauration : moins d'interruptions lors des incantations, les dégâts du Naturaliste, régénération en incantation et soins plus puissants."
L["Ferocity first: cheaper Claw, Rake and Maul in both forms."] = "Férocité en premier : Griffure, Balafre et Fracassement moins chers dans les deux formes."
L["Savage Fury and Sharpened Claws add damage and crit in Cat and Bear Form."] = "Fureur sauvage et Griffes acérées ajoutent des dégâts et du critique en Forme Félin et Forme Ours."
L["Predatory Strikes adds attack power in forms; it scales with your level, not your gear."] = "Attaques prédatrices ajoute de la puissance d'attaque dans les formes ; cela évolue avec votre niveau, pas votre équipement."
L["Leader of the Pack adds crit for you and your group."] = "Guide du troupeau ajoute du critique pour vous et votre groupe."
L["Berserk is the capstone: a cooldown that makes Primal Bite hit several targets."] = "Berserk est le capstone : un temps de recharge qui fait que Morsure primale frappe plusieurs cibles."
L["The last 20 points go to Restoration: rage when you shift, Naturalist's damage, cheaper shifting and regen while casting."] = "Les 20 derniers points vont en Restauration : rage lors des changements de forme, les dégâts du Naturaliste, changements de forme moins chers et régénération en incantation."
L["Nature's Focus first: your casts go through while a mob hits you."] = "Concentration de la nature en premier : vos sorts passent pendant qu'un monstre vous frappe."
L["Reflection keeps mana coming back while casting, so you rest less."] = "Réflexion maintient la régénération de mana pendant l'incantation, vous vous reposez donc moins."
L["Swiftmend uses up a Rejuvenation or Regrowth for a big instant heal."] = "Guérison prompte consomme un Rejuvénation ou Repousse pour une grande guérison instantanée."
L["Wild Growth is the capstone: a heal over time on your whole group."] = "Croissance sauvage est le capstone : un soin sur la durée pour tout votre groupe."
L["The last 20 points go to Balance so you can still kill quest mobs: a faster, cheaper Wrath, roots and more crit."] = "Les 20 derniers points vont en Équilibre pour encore tuer les monstres de quête : un Courroux plus rapide et moins cher, des racines et plus de critique."
L["Level as Enhancement (Flurry, Stormstrike, Maelstrom Weapon) for steady melee with few rests, or Elemental (Lightning Overload, Lava Burst) to kill from range. Restoration heals dungeons well and levels slowly alone."] = "Montez en niveau en Amélioration (Tornade, Frappe de tempête, Arme du Maëlstrom) pour un corps-à-corps régulier avec peu de repos, ou en Élémentaire (Surcharge élémentaire, Éruption de lave) pour tuer à distance. Restauration soigne bien les donjons et monte seul lentement."
L["Concussion first: more damage from Lightning Bolt and Earth Shock, your two main spells."] = "Commotion en premier : plus de dégâts de l'Éclair et Choc de terre, vos deux sorts principaux."
L["Elemental Focus makes some casts free, which is the main mana saver for the early levels."] = "Concentration élémentaire rend certains sorts gratuits, ce qui est le principal économiseur de mana pour les premiers niveaux."
L["Lava Burst is a big Fire nuke, best after Flame Shock; Call of Flame makes it stronger."] = "Éruption de lave est un puissant sort de Feu, meilleur après Choc de flammes ; Appel de la flamme le renforce."
L["Lightning Overload sometimes casts a second, smaller Lightning Bolt for free."] = "Surcharge élémentaire lance parfois un deuxième Éclair plus petit gratuitement."
L["Elemental Mastery is the capstone: for a while, quicker Lightning Bolts and Lava Bursts and no cooldown on Chain Lightning."] = "Maîtrise élémentaire est le capstone : pendant un moment, des Éclairs et Éruptions de lave plus rapides et sans temps de recharge sur l'Éclair en chaîne."
L["The last 20 points go to Enhancement: more Intellect, more crit, a stronger Lightning Shield and cheaper Shocks."] = "Les 20 derniers points vont en Amélioration : plus d'Intellect, plus de critiques, un Bouclier de foudre plus fort et des Chocs moins chers."
L["Thundering Strikes first: crit for spells and attacks, and the way into the tree."] = "Coups tonnants en premier : critique pour les sorts et les attaques, et la voie dans l'arbre."
L["Mental Dexterity turns your Intellect into attack power, so mana gear helps your melee too; it also opens Flurry."] = "Dextérité mentale transforme votre Intellect en puissance d'attaque, donc l'équipement de mana aide aussi votre corps-à-corps ; cela ouvre aussi Tornade."
L["Flurry speeds up your swings after a crit and is the core of Enhancement's damage."] = "Tornade accélère vos attaques après un critique et est le cœur des dégâts d'Amélioration."
L["Stormstrike is an instant strike that raises the damage your next spells do."] = "Frappe de tempête est un coup instantané qui augmente les dégâts de vos prochains sorts."
L["Maelstrom Weapon makes your next Lightning Bolt faster and cheaper as you hit."] = "Arme du Maëlstrom rend votre prochain Éclair plus rapide et moins cher à mesure que vous frappez."
L["Rage of the Farseer is the capstone: a big attack-speed cooldown for elites and pulls."] = "Rage du Voyant est le capstone : un grand temps de recharge de vitesse d'attaque pour les élites et les pulls."
L["The last 20 points go to Elemental for stronger Shocks, cheaper casts and more crit from spells."] = "Les 20 derniers points vont en Élémentaire pour des Chocs plus puissants, des incantations moins chères et plus de critiques des sorts."
L["Tidal Focus first: cheaper heals, and more hit for your Lightning Bolts while you quest."] = "Concentration des marées en premier : des soins moins chers et plus de toucher pour vos Éclairs pendant vos quêtes."
L["Totemic Focus: cheaper totems, which you drop on every pull while leveling."] = "Concentration totémique : des totems moins chers, que vous posez à chaque pull en leveling."
L["Mindfulness keeps half your mana regeneration going while casting."] = "La Vigilance maintient la moitié de votre régénération de mana pendant l'incantation."
L["Nature's Swiftness makes one heal instant: your emergency button."] = "Rapidité de la nature rend un soin instantané : votre bouton d'urgence."
L["Riptide is the capstone: a quick heal with a heal over time for dungeons."] = "Ressac est le capstone : un soin rapide avec un soin sur la durée pour les donjons."
L["The last 20 points go to Elemental, so your Lightning Bolts and Shocks still kill while you quest."] = "Les 20 derniers points vont en Élémentaire, afin que vos Éclairs et Chocs puissent encore tuer pendant vos quêtes."
L["Feral Combat"] = "Combat farouche"
L["Restoration"] = "Restauration"
L["Level as Beast Mastery: your pet tanks and does much of the damage, so you rarely stop. Marksmanship hits harder from range with Careful Aim and Sniper Shot; Survival fights in melee with Predator's Edge and Lacerating Strikes."] = "Montez en niveau en Maîtrise des bêtes : votre familier tanke et fait beaucoup des dégâts, donc vous vous arrêtez rarement. Tir d'élite frappe plus fort à distance avec Visée précise et Tir de tireur d'élite ; Survie combat en mêlée avec Atout du prédateur et Griffures lacérantes."
L["Deadly Aspects first: more from Aspect of the Hawk while your pet holds the mob."] = "Aspects mortels en premier : plus de l'Aspect du faucon pendant que votre familier retient le monstre."
L["Unleashed Fury adds pet damage, and your pet is most of your damage."] = "Furie déchaînée ajoute des dégâts de familier, et votre familier représente la plupart de vos dégâts."
L["Intimidation stuns through your pet: a breather when a mob turns on you."] = "Intimidation étourdit via votre familier : un répit quand un monstre se retourne contre vous."
L["Bestial Wrath is the capstone: your pet's big damage cooldown."] = "Colère bestiale est le capstone : le grand temps de recharge de dégâts de votre familier."
L["The last 20 points go to Marksmanship: more crit, attack power from Intellect, a shorter Rapid Fire and harder ranged crits."] = "Les 20 derniers points vont en Tir d'élite : plus de critiques, puissance d'attaque de l'Intellect, un Tir rapide plus court et des critiques à distance plus forts."
L["Lethal Attacks first: crit for every shot."] = "Attaques mortelles en premier : critique pour chaque tir."
L["Careful Aim adds attack power from your Intellect."] = "Visée précise ajoute de la puissance d'attaque depuis votre Intellect."
L["Mortal Shots makes your ranged crits hit much harder."] = "Tirs mortels fait frapper beaucoup plus fort vos critiques à distance."
L["Sniper Shot is the capstone: a long-range opener that hits hard."] = "Tir de tireur d'élite est le capstone : un ouvreur longue portée qui frappe fort."
L["The last 20 points go to Beast Mastery: a stronger Aspect of the Hawk and a tougher, harder-hitting pet."] = "Les 20 derniers points vont en Maîtrise des bêtes : un Aspect du faucon plus fort et un familier plus résistant et frappant plus fort."
L["Improved Tracking first: keep tracking on for its bonus against the mobs you quest on."] = "Pistage amélioré en premier : gardez le Pistage actif pour son bonus contre les monstres sur lesquels vous quêtez."
L["Deterrence is a dodge and parry cooldown for melee fights that go wrong."] = "Dissuasion est un temps de recharge d'esquive et de parade pour les combats de mêlée qui tournent mal."
L["Lightning Reflexes adds Agility: more attack power, crit and dodge."] = "Réflexes foudroyants ajoute de l'Agilité : plus de puissance d'attaque, de critique et d'esquive."
L["Lacerating Strikes is the capstone: Mongoose Bite also makes the target bleed."] = "Griffures lacérantes est le capstone : Morsure de mangouste fait aussi saigner la cible."
L["Level as Shadow (Spirit Tap, Mind Flay, Shadowform) for the fastest kills and least drinking. Discipline levels with Smite and Penance behind a strong shield; Holy is the dungeon healer and slower alone."] = "Montez en niveau en Ombre (Toucher l'esprit, Effilochage mental, Forme d'ombre) pour les kills les plus rapides et le moins de boissons. Discipline monte en niveau avec Châtiment et Pénitence derrière un bouclier fort ; Sacré est le guérisseur de donjon et plus lent seul."
L["Power in Light first: more Smite damage, your main attack as Discipline, on targets with your Holy Fire or Shadow Word: Pain."] = "Puissance dans la Lumière en premier : plus de dégâts de Châtiment, votre principale attaque en Discipline, sur des cibles avec votre Feu sacré ou Mot de l'ombre : Douleur."
L["Improved Power Word: Shield: a bigger shield is fewer interrupted casts and less healing."] = "Mot de pouvoir amélioré : Bouclier : un plus grand bouclier signifie moins d'incantations interrompues et moins de soins."
L["Penance is a channelled burst of Holy damage or healing: use it on every mob."] = "Pénitence est une explosion canalisée de dégâts ou de soins sacrés : utilisez-le sur chaque monstre."
L["Power Infusion is the capstone: a damage and healing cooldown for you or an ally."] = "Infusion de puissance est le capstone : un temps de recharge de dégâts et de soins pour vous ou un allié."
L["The last 20 points go to Shadow: Spirit Tap's regen after kills, a longer Shadow Word: Pain, more Shadow hit, Mind Flay and a quicker Mind Blast."] = "Les 20 derniers points vont en Ombre : la régénération de Toucher l'esprit après les kills, un Mot de l'ombre : Douleur plus long, plus de toucher d'Ombre, Effilochage mental et un Blast mental plus rapide."
L["Holy Specialization first: more crits on Smite and on your heals."] = "Spécialisation sacrée en premier : plus de critiques sur Châtiment et vos soins."
L["Divine Fury speeds up Smite, Holy Fire and your big heals."] = "Fureur divine accélère Châtiment, Feu sacré et vos grands soins."
L["Spiritual Guidance adds 25% of your Spirit to your healing but only 8% to your damage: Spirit gear helps your heals most."] = "Direction spirituelle ajoute 25% de votre Esprit à vos soins mais seulement 8% à vos dégâts : l'équipement d'Esprit aide surtout vos soins."
L["Prayer of Mending is the capstone: a heal that jumps between your group as they take damage."] = "Prière de soin est le capstone : un soin qui saute entre les membres de votre groupe à mesure qu'ils subissent des dégâts."
L["The last 20 points go to Discipline: a stronger wand, a bigger Power Word: Shield, Meditation's regen while casting and more Intellect."] = "Les 20 derniers points vont en Discipline : une baguette plus puissante, un Mot de pouvoir : Bouclier plus grand, régénération de Méditation en incantation et plus d'Intellect."
L["Mental Strength comes last: on Forever its points do not count toward the Discipline tiers."] = "Force mentale vient en dernier : sur Forever, ses points ne comptent pas pour les niveaux de Discipline."
L["Spirit Tap first: after each kill your regen jumps, so you drink far less."] = "Toucher l'esprit en premier : après chaque kill votre régénération bondit, vous buvez donc bien moins."
L["Mind Flay is your main damage and slow from here; Improved Mind Flay makes it hit harder."] = "Effilochage mental est votre principal dégât et ralentissement à partir d'ici ; Effilochage mental amélioré le fait frapper plus fort."
L["Vampiric Embrace heals you from your Shadow damage."] = "Étreinte vampirique vous soigne grâce à vos dégâts d'Ombre."
L["Shadowform is the capstone: more Shadow damage and less physical damage taken."] = "Forme d'ombre est le capstone : plus de dégâts d'Ombre et moins de dégâts physiques subis."
L["ForeverDB through level 30, Polestar after"] = "ForeverDB jusqu'au niveau 30, Polestar ensuite"
L["Polestar, with ForeverDB's builds to level 20"] = "Polestar, avec les builds de ForeverDB jusqu'au niveau 20"
L["Polestar, with ForeverDB's talent data"] = "Polestar, avec les données de talents de ForeverDB"
L["ForeverDB"] = "ForeverDB"
L["ForeverDB's leveling builds, adapted to level 30"] = "Builds de montée en niveau de ForeverDB, adaptés au niveau 30"

-- Nav/Handoff.lua
L["Hand guiding to Shortest Path Forever"] = "Confier le guidage à Shortest Path Forever"
L["Shortest Path Forever's arrow, route and journey take you to each goal. Polestar's arrow, route lines, journey steps, travel button, transport alerts, map clicks and /way step aside; the guide window and map pins stay. Off: Polestar guides, and steps aside only while a journey you started in Shortest Path Forever runs."] = "La flèche, l'itinéraire et le trajet de Shortest Path Forever vous mènent à chaque objectif. La flèche de Polestar, ses lignes d'itinéraire, les étapes du trajet, le bouton de voyage, les alertes de transport, les clics sur la carte et /way s'effacent ; la fenêtre du guide et les marques de la carte restent. Désactivé : Polestar guide, et ne s'efface que pendant un trajet lancé dans Shortest Path Forever."

-- Core/Import.lua
L["Imported"] = "Importés"
L["This import string is damaged or incomplete. Copy the whole string again."] = "Ce texte d'import est abîmé ou incomplet. Copiez-le de nouveau en entier."
L["This import string needs a newer Polestar."] = "Ce texte d'import demande un Polestar plus récent."
L["This import string holds no guide."] = "Ce texte d'import ne contient aucun guide."
L["Its guide id %s must start with its author's own id, as in yendi/cozy-sleeping-bag."] = "L'identifiant de son guide, %s, doit commencer par l'identifiant propre de son auteur, comme dans yendi/cozy-sleeping-bag."
L["Guides under %s/ come from the community addon %s, which is installed."] = "Les guides sous %s/ viennent de l'addon communautaire %s, qui est installé."
L["Its guide has %d steps; an import string holds %d at most. A bigger guide comes as a community addon."] = "Son guide a %d étapes ; un texte d'import en contient %d au plus. Un guide plus grand vient sous forme d'addon communautaire."
L["It leads on to %s, which is neither one of Polestar's guides nor an imported one: import that guide first."] = "Il mène ensuite à %s, qui n'est ni un guide de Polestar ni un guide importé : importez d'abord ce guide."
L["This import string holds a field Polestar does not read (%s). It may need a newer Polestar."] = "Ce texte d'import contient un champ que Polestar ne lit pas (%s). Il demande peut-être un Polestar plus récent."
L["Paste an import string."] = "Collez un texte d'import."
L["This import string is too long: Polestar reads up to %d characters."] = "Ce texte d'import est trop long : Polestar lit jusqu'à %d caractères."
L["This is not a Polestar import string."] = "Ce n'est pas un texte d'import Polestar."
L["This game client cannot read import strings."] = "Ce client de jeu ne sait pas lire les textes d'import."
L["This import string holds a text longer than Polestar reads (%s): %d characters at most."] = "Ce texte d'import contient un texte plus long que ce que Polestar lit (%s) : %d caractères au plus."
L["This import string holds too much: Polestar reads up to %d KB of guide data."] = "Ce texte d'import contient trop de données : Polestar lit jusqu'à %d Ko de données de guide."
L["Its guide has %d goals in step %d; an import string holds %d per step at most."] = "Son guide a %d objectifs à l'étape %d ; un texte d'import en contient %d par étape au plus."
L["Its guide has %d candidates in a goal; an import string holds %d per goal at most."] = "Son guide a %d candidats dans un objectif ; un texte d'import en contient %d par objectif au plus."
L["Its guide has more than one direct turn-in for quest %d in step %d."] = "Son guide a plus d'un rendu direct pour la quête %d à l'étape %d."
L["Its guide has a candidate coordinate outside 0-100."] = "Son guide a une coordonnée de candidat hors de 0-100."
L["Its guide has a spot coordinate outside 0-100."] = "Son guide a une coordonnée de lieu hors de 0-100."
L["Its guide has a map frame with missing fields."] = "Son guide a un cadre de carte avec des champs manquants."
L["Its guide has a degenerate map frame (zero extent)."] = "Son guide a un cadre de carte dégénéré (étendue nulle)."
L["Its guide has a map frame with out-of-range coordinates."] = "Son guide a un cadre de carte avec des coordonnées hors limites."
L["No imported guides to remove."] = "Aucun guide importé à supprimer."
L["Removed %d imported guide(s)."] = "%d guide(s) importé(s) supprimé(s)."
L["Usage: /polestar import delete <guide-id>"] = "Utilisation : /polestar import delete <guide-id>"
L["Removed imported guide %s."] = "Guide importé %s supprimé."
L["No imported guide with id %s."] = "Aucun guide importé avec l'identifiant %s."
L["Open the Import page; import clear / import delete <id>: remove imports"] = "Ouvrir la page d'import ; import clear / import delete <id> : supprimer les imports"
L["Its guide has %d entries in %s; an import string holds %d there at most."] = "Son guide a %d entrées dans %s ; un texte d'import en contient %d au plus à cet endroit."

-- UI/Import.lua
L["by %s"] = "par %s"
L["1 step"] = "1 étape"
L["%d steps"] = "%d étapes"
L["levels %d–%d"] = "niveaux %d–%d"
L["Alliance and Horde"] = "Alliance et Horde"
L["You have version %s of this guide. Update replaces it and keeps your progress where its steps are unchanged."] = "Vous avez la version %s de ce guide. Mettre à jour la remplace et garde votre progression là où ses étapes n'ont pas changé."
L["This guide is already imported, at this version."] = "Ce guide est déjà importé, dans cette version."
L["You have a newer version (%s) of this guide imported."] = "Vous avez importé une version plus récente (%s) de ce guide."
L["Updated %s."] = "%s mis à jour."
L["Imported %s. Find it in the guide menu under Community guides, Imported."] = "%s importé. Il se trouve dans le menu des guides, sous Guides de la communauté, Importés."
L["Paste an import string here (Ctrl+V)"] = "Collez un texte d'import ici (Ctrl+V)"
L["Delete"] = "Supprimer"
L["Two ways to bring someone else's guides into Polestar. Pick the one that fits."] = "Deux façons d'ajouter à Polestar les guides de quelqu'un d'autre. Choisissez celle qui convient."
L["Import string"] = "Texte d'import"
L["One small guide: a quest chain, an item, a mount, an errand."] = "Un petit guide : une suite de quêtes, un objet, une monture, une course."
L["Its author shares it as text, anywhere. Paste it below."] = "Son auteur le partage sous forme de texte, n'importe où. Collez-le ci-dessous."
L["Updates: paste the newer string, then Update."] = "Mises à jour : collez le texte plus récent, puis Mettre à jour."
L["One guide of up to %d steps."] = "Un guide de %d étapes au plus."
L["Community addon"] = "Addon communautaire"
L["A whole route or a set of guides: a leveling route, every profession."] = "Un itinéraire entier ou un ensemble de guides : un itinéraire de montée en niveau, tous les métiers."
L["Install it like any addon, then restart the game."] = "Installez-le comme n'importe quel addon, puis redémarrez le jeu."
L["Updates: your addon app updates it."] = "Mises à jour : votre application d'addons s'en charge."
L["No size limit."] = "Pas de limite de taille."
L["Paste a string"] = "Coller un texte"
L["Import"] = "Importer"
L["No imported guides yet."] = "Aucun guide importé pour l'instant."
L["Want more than one guide?"] = "Plus d'un guide ?"
L["A set of guides, or one too big for a string, comes as a community addon:"] = "Un ensemble de guides, ou un guide trop grand pour un texte, vient sous forme d'addon communautaire :"
L["Get it from wherever its author publishes it."] = "Procurez-le là où son auteur le publie."
L["Its guides appear in the guide menu under Community guides, with the author's name. Options, Community guides turns it on or off."] = "Ses guides apparaissent dans le menu des guides sous Guides de la communauté, avec le nom de l'auteur. Options, Guides de la communauté l'active ou le désactive."
L["Update"] = "Mettre à jour"
L["Your imported guides"] = "Vos guides importés"
L["version %s"] = "version %s"
L["Guides someone shared with you, as an import string or a community addon."] = "Les guides que quelqu'un partage avec vous, en texte d'import ou en addon communautaire."
L["The author differs from the stored guide's."] = "L'auteur diffère de celui du guide enregistré."
L["The licence differs from the stored guide's."] = "La licence diffère de celle du guide enregistré."

-- Nav/Pins.lua
L["Polestar trail dots"] = "Points de piste de Polestar"

-- UI/LineStyle.lua
