L["Every route reviewed"] = "Tous les itinéraires revus"
L["The arrow finds your targets"] = "La flèche trouve vos cibles"
L["More quests and shorter grinds at 40-60, fewer walk-backs, no pointless travel steps."] = "Plus de quêtes et moins de farm en 40-60, moins d'allers-retours, aucune étape de trajet inutile."
L["Dynamic Questing saves trips"] = "Les quêtes dynamiques évitent des trajets"
L["Hand in and pick up at NPCs on your way; auto-accept takes the next steps' quests."] = "Rendez et prenez les quêtes des PNJ sur votre route ; l'acceptation auto prend celles des étapes suivantes."
L["Grinds go to the nearest spawns, past emptied camps; Target shows who, pings, marks."] = "Le farm mène aux apparitions les plus proches, sans les camps vidés ; Cibler montre qui, pingue, marque."
