L["Keeps up on slopes and ledges, takes the faster flight, and no turning back after you land."] = "Tient bon sur les pentes et les rebords, prend le vol le plus rapide, plus de demi-tour à l'atterrissage."
L["Smoother indoors"] = "Plus fluide en intérieur"
L["No more stutter in the Undercity, buildings and caves; less work in the background."] = "Plus de saccades à Fossoyeuse, dans les bâtiments et les grottes ; moins de travail en arrière-plan."
