-- L["Shortest Path Forever is guiding. Turn off \"Guide with Shortest Path Forever when it's installed\" (Options, Arrow & routes) to use Polestar's arrow."] = "Shortest Path Forever guide. Désactivez « Guider avec Shortest Path Forever s'il est installé » (Options, Flèche et itinéraires) pour utiliser la flèche de Polestar."
-- L["Shortest Path Forever is guiding. Turn off \"Guide with Shortest Path Forever when it's installed\" (Options, Integrations) to use Polestar's arrow."] = "Shortest Path Forever guide. Désactivez \"Guider avec Shortest Path Forever s'il est installé\" (Options, Intégrations) pour utiliser la flèche de Polestar."
-- L["Guide with Shortest Path Forever when it's installed"] = "Guider avec Shortest Path Forever s'il est installé"
-- L["Shortest Path Forever's arrow, route and journey take you to each goal. Polestar's arrow, route lines, journey steps, travel button, transport alerts, map clicks and /way step aside; the guide window and map pins stay."] = "La flèche, l'itinéraire et le trajet de Shortest Path Forever vous mènent à chaque objectif. La flèche de Polestar, ses lignes d'itinéraire, les étapes du trajet, le bouton de voyage, les alertes de transport, les clics sur la carte et /way s'effacent ; la fenêtre du guide et les marques de la carte restent."
-- L["Browsing the guide needs a gamepad: turn it on in the game's options and plug one in."] = "Parcourir le guide nécessite une manette : activez-la dans les options du jeu et branchez-en une."
-- L["Follow a talent plan for your class and spec (/pole talents). Paladin only for now."] = "Suivre un plan de talents pour votre classe et votre spécialisation (/pole talents). Paladin seulement pour l'instant."
-- L["Talent plans cover the Paladin for now. More classes will follow."] = "Les plans de talents couvrent le paladin pour l'instant. D'autres classes suivront."
-- L["The game's own font (the default), Inter, or EllesmereUI's."] = "La police du jeu (par défaut), Inter, ou celle d'EllesmereUI."
-- L["Your report"] = "Votre rapport"
-- L["Select report"] = "Sélectionner le rapport"
-- L["Copy your report with Ctrl+C (Cmd+C on a Mac), switch to Discord and paste it in the Polestar server. Not in it yet? Get the invite once and open it in your browser."] = "Copiez votre rapport avec Ctrl+C (Cmd+C sur Mac), passez sur Discord et collez-le sur le serveur Polestar. Pas encore membre ? Obtenez l'invitation et ouvrez-la dans votre navigateur."
-- L["Next boat in about %s"] = "Prochain bateau dans environ %s"
-- L["Next zeppelin in about %s"] = "Prochain zeppelin dans environ %s"
-- L["Next tram in about %s"] = "Prochain tram dans environ %s"
-- L["Next lift in about %s"] = "Prochain ascenseur dans environ %s"
-- L["leaves in about %s"] = "départ dans environ %s"
-- L["Scale of the quest item, Hearthstone and target buttons. Drag one to move them all."] = "Échelle des boutons d'objet de quête, de pierre de foyer et de ciblage. Faites-en glisser un pour tous les déplacer."
-- L["Route"] = "Itinéraire"
-- L["Open the Import page: guides shared as text"] = "Ouvrir la page Importer : les guides partagés sous forme de texte"
-- L["WoW Forever"] = "WoW Forever"
-- L["Take %s"] = "Prenez %s"
-- L["Take the lift"] = "Prenez l'ascenseur"
-- L["The step you are on."] = "L'étape en cours."
-- L["Points the way."] = "Montre le chemin."
-- L["The map marks each place."] = "La carte indique chaque lieu."
-- L["Planned in a simulator and played to the end in tests, but nobody has followed them through the live game yet. Skip a wrong step with %s and tell us on Discord."] = "Planifiés dans un simulateur et joués jusqu'au bout en test, mais personne ne les a encore suivis en jeu réel. Passez une étape erronée avec %s et dites-le-nous sur Discord."
-- L["Feedback, bug reports and news"] = "Avis, rapports de bugs et nouvelles"
-- L["Guides made by other players for Polestar, not our own routes: each community addon is installed like any other addon. Its guides appear in %s under Community guides, credited to their author, who supports them. More in Options > Community guides."] = "Des guides écrits par d'autres joueurs pour Polestar, pas nos propres itinéraires : chaque addon communautaire s'installe comme n'importe quel addon. Ses guides apparaissent dans %s sous Guides de la communauté, au nom de leur auteur, qui les maintient. Plus d'infos dans Options > Guides de la communauté."
-- L["How the arrow walks you. You can change it any time in Options."] = "Comment la flèche vous guide. Modifiable à tout moment dans les Options."
-- L["Sessions stored"] = "Sessions stockées"
-- L["Kept in SavedVariables until imported with the toolchain."] = "Conservées dans SavedVariables jusqu'à l'import par les outils."
-- L["Events this session"] = "Événements de cette session"
-- L["Character"] = "Personnage"
-- L["Session"] = "Session"
-- L["Counts and the current session in chat."] = "Compteurs et session en cours dans la discussion."
-- L["Opens the gate of the Horde's way into the City of Dalaran; one key opens it for the group. The Alliance is sent in by the Image of Archmage Modera."] = "Ouvre la porte du chemin de la Horde vers la cité de Dalaran ; une clé l'ouvre pour tout le groupe. L'Alliance y est envoyée par l'Image de l'archimage Modera."
-- L["Accepted a resurrection."] = "Résurrection acceptée."
-- L["The item the current step uses, or a quest item it collects, glows in your bags (and in Baganator)."] = "L'objet qu'utilise l'étape en cours, ou un objet de quête qu'elle fait ramasser, brille dans vos sacs (et dans Baganator)."
-- L["Sells Poor-quality items when a merchant opens and prints the total. Never sells anything else."] = "Vend les objets de qualité médiocre à l'ouverture d'un marchand et affiche le total. Ne vend jamais rien d'autre."
-- L["Picks the only option of NPCs without quests. Hold Shift to read it."] = "Choisit l'unique option des PNJ sans quête. Maintenez Maj pour la lire."
-- L["Earlier quests of this chain are not listed."] = "Les quêtes précédentes de cette suite ne sont pas listées."
-- L["Small conveniences: travel, invitations, merchants and trackers."] = "Petites commodités : voyages, invitations, marchands et suivis."
-- L["Party members who run Polestar see your counts under their quest goals. Nothing goes to chat."] = "Les membres du groupe qui utilisent Polestar voient vos compteurs sous leurs objectifs de quête. Rien ne passe par le chat."
-- L["Their counts under your quest goals, and who lacks a quest you took."] = "Leurs compteurs sous vos objectifs de quête, et qui n'a pas une quête que vous avez prise."
-- L["Share %s with %s"] = "Partager %s avec %s"
-- L["Click to share the quest with your party."] = "Cliquez pour partager la quête avec votre groupe."
-- L["Each Polestar member's level, step and what they still need of yours; click a name to point the arrow at them. /polestar party shows or hides it."] = "Le niveau et l'étape de chaque membre Polestar, et ce qu'il lui reste de la vôtre ; cliquez sur un nom pour y pointer la flèche. /polestar party l'affiche ou le masque."
-- L["In dungeons"] = "En donjon"
-- L["What the window does in dungeons and raids. /polestar or the key binding opens it there until you leave."] = "Ce que fait la fenêtre en donjon et en raid. /polestar ou le raccourci l'y ouvre jusqu'à votre sortie."
-- L["%s from another version"] = "%s d'une autre version"
-- L["Polestar %s is installed incompletely: %s. Close the game, delete every Polestar folder in Interface/AddOns and unzip the latest Polestar zip there (CurseForge or GitHub Releases, not \"Source code\")."] = "Polestar %s est installé de façon incomplète : %s. Fermez le jeu, supprimez tous les dossiers Polestar dans Interface/AddOns et décompressez-y la dernière archive Polestar (CurseForge ou GitHub Releases, pas « Source code »)."
-- L["About %d bars short of level %s by step %d"] = "Il manquera environ %d barres pour le niveau %s à l'étape %d"
-- L["Objective areas"] = "Zones d'objectif"
-- L["Shade the area each group of mobs or objects spreads over on the world map."] = "Ombrer sur la carte du monde la zone couverte par chaque groupe de monstres ou d'objets."
-- L["The target button and the step key put a raid icon on the mob and the NPC they target; out of combat, a press that finds neither clears your target. Your party sees the icons; in a raid only the leader and assistants can set them."] = "Le bouton de ciblage et la touche d'étape placent une icône de raid sur le monstre et le PNJ qu'ils ciblent ; hors combat, un appui qui ne trouve ni l'un ni l'autre efface votre cible. Votre groupe voit les icônes ; en raid, seuls le chef et les assistants peuvent les placer."
-- L["The last guides you loaded."] = "Les derniers guides chargés."
-- L["Three choices to start with. Everything else is in %s."] = "Trois choix pour commencer. Tout le reste est dans %s."
-- L["The way to the goal on the world map and the minimap: dots where you walk, lines where you fly, sail or ride, the legs after this one fainter. Drawn as Shortest Path Forever by Cillian Berragan draws them."] = "Le chemin vers l'objectif sur la carte et la minicarte : des points là où vous marchez, des lignes là où vous volez, naviguez ou voyagez, les tronçons suivants plus pâles. Dessiné comme le fait Shortest Path Forever par Cillian Berragan."
-- L["How the route lines are drawn: Polestar's dots, or sparkles that drift along the way to the goal."] = "Comment les lignes d'itinéraire sont tracées : les points de Polestar, ou des étincelles qui dérivent le long du chemin vers l'objectif."
-- L["The first walk of %s"] = "Le premier trajet de %s"
-- L["Browse folders fold away, a closed tab comes back with Reopen, the route line can be a line, dots or sparkles on the map and minimap, and a floating Polestar button can be turned on in Options."] = "Les dossiers de navigation se replient, un onglet fermé revient avec Rouvrir, l'itinéraire peut s'afficher en ligne, en points ou en étincelles sur la carte et la minicarte, et un bouton Polestar flottant peut être activé dans les Options."
-- L["Found something off?"] = "Quelque chose cloche ?"
-- L["Type %s right where it happens."] = "Tapez %s à l'endroit même où cela se produit."
-- L["Guide menu and minimap"] = "Menu des guides et minicarte"
-- L["Quests asked for before the game offers them, wrong spots, dungeon pick-ups, guides opened part-way, the arrow while you're a ghost, and lots more."] = "Quêtes demandées avant que le jeu ne les propose, mauvais emplacements, quêtes de donjon à prendre, guides ouverts en cours de route, la flèche quand vous êtes un fantôme, et bien plus."
-- L["Grinding steps point at where the mob is found, and on a step with several camps the arrow moves on from one you've emptied. The Target button shows who it targets, the While you're here mobs included."] = "Les étapes de farm pointent vers l'endroit où se trouve le monstre, et sur une étape à plusieurs camps la flèche quitte celui que vous avez vidé. Le bouton de ciblage montre qui il cible, monstres de « Tant que vous êtes là » compris."
-- L["Every leveling guide was gone over again, and 40-60 reworked for both factions with more quests and shorter grinds. Quests new in Forever carry a small ∞ mark. If the guide you had open doesn't match where you are, open the guide list and pick the guide under %s. Your quest log carries over."] = "Chaque guide de montée de niveau a été revu, et le 40-60 retravaillé pour les deux factions avec plus de quêtes et moins de farm. Les quêtes nouvelles dans Forever portent une petite marque ∞. Si le guide que vous aviez ouvert ne correspond pas à l'endroit où vous êtes, ouvrez la liste des guides et choisissez le guide sous %s. Votre journal des quêtes est conservé."
-- L["Browse folders fold away, a closed tab comes back with Reopen, the route line can be a line, dots or sparkles on the map and minimap, and the minimap button and a floating Polestar button can be turned on in Options."] = "Les dossiers de navigation se replient, un onglet fermé revient avec Rouvrir, l'itinéraire peut s'afficher en ligne, en points ou en étincelles sur la carte et la minicarte, et le bouton de la minicarte et un bouton Polestar flottant peuvent être activés dans les Options."
-- L["Leveling guides take you through this dungeon where they have steps for it. Off: they keep to the solo route."] = "Les guides de montée en niveau vous font passer par ce donjon quand ils ont des étapes pour lui. Désactivé : ils s'en tiennent à l'itinéraire solo."
-- L["With Transparent, a shade with no edge behind the text, so it reads over bright ground. Off: the outlined text alone on the world."] = "Avec Transparent, une ombre sans bord derrière le texte, pour qu'il reste lisible sur un décor clair. Désactivé : le texte détouré seul sur le monde."
-- L["The route's line, dots or sparkles on the minimap, and the gaps between the dots; the world map keeps its own. Right-click to reset."] = "La ligne, les points ou les étincelles de l'itinéraire sur la minicarte, et les espaces entre les points ; la carte du monde garde les siens. Clic droit pour réinitialiser."
-- L["Behind: %s (%d) at step %d, you'll be %s; grind ~%s first"] = "En retard : %s (%d) à l'étape %d, vous serez %s ; farmez ~%s avant"
-- L["Behind: %s (%d) at step %d, you'll be %s; reach %d first"] = "En retard : %s (%d) à l'étape %d, vous serez %s ; atteignez %d avant"
-- L["1 bar"] = "1 barre"
-- L["%d bars"] = "%d barres"
-- L["On pace, but %s (%d) at step %d is hard: you'll be %s; grind ~%s first"] = "En bonne voie, mais %s (%d) à l'étape %d est difficile : vous serez %s ; farmez ~%s avant"
-- L["On pace, but %s (%d) at step %d is hard: you'll be %s; reach %d first"] = "En bonne voie, mais %s (%d) à l'étape %d est difficile : vous serez %s ; atteignez %d avant"
-- L["%s has Polestar %s; you have %s. A newer version is out."] = "%s a Polestar %s ; vous avez %s. Une version plus récente est disponible."
-- L["Party sync is on: your party sees your quest progress (Options > Questing > Quests > Group to turn it off)."] = "La synchro de groupe est active : votre groupe voit votre progression de quêtes (à désactiver dans Options > Quêtes > Quêtes > Groupe)."
-- L["Hide the guide window"] = "Masquer la fenêtre du guide"
-- L["A Polestar button on the edge of the minimap. Click to show or hide the guide, right-click for settings, drag to move it."] = "Un bouton Polestar au bord de la minicarte. Cliquez pour afficher ou masquer le guide, clic droit pour les réglages, faites-le glisser pour le déplacer."
-- L["Click the minimap button or press %s to show it."] = "Cliquez sur le bouton de la minicarte ou appuyez sur %s pour l'afficher."
-- L["Click the minimap button to show it."] = "Cliquez sur le bouton de la minicarte pour l'afficher."
-- L["What the window, its buttons and alerts do in dungeons, raids, battlegrounds and arenas. The minimap button, the key binding or /polestar opens it there until you leave."] = "Ce que font la fenêtre, ses boutons et ses alertes dans les donjons, raids, champs de bataille et arènes. Le bouton de la minicarte, le raccourci clavier ou /polestar l'y ouvre jusqu'à ce que vous en sortiez."
-- L["A small Polestar button you can put anywhere on the screen. Click to show or hide the guide, right-click for a menu, drag to move it. It hides with the window in combat and in dungeons when those are set to Hide."] = "Un petit bouton Polestar que vous pouvez placer n'importe où sur l'écran. Cliquez pour afficher ou masquer le guide, clic droit pour un menu, faites-le glisser pour le déplacer. Il se masque avec la fenêtre en combat et dans les donjons quand ceux-ci sont réglés sur Masquer."
-- L["Click: show or hide the guide"] = "Clic : afficher ou masquer le guide"
-- L["Show window"] = "Afficher la fenêtre"
-- L["How near its spawn area must be for a suggestion to show. It goes again a little further out."] = "À quelle distance sa zone d'apparition doit se trouver pour qu'une suggestion s'affiche. Elle disparaît un peu plus loin."
-- L["Clears your manual check-offs and skipped steps for this guide."] = "Efface vos cases cochées et étapes passées pour ce guide."
-- L["Manual check-offs and skips, current guide."] = "Coches manuelles et étapes passées, guide actuel."
-- L["Your manual check-offs and skipped steps in %s are cleared. Quests you have done stay done."] = "Vos cases cochées et étapes passées dans %s sont effacées. Les quêtes faites restent faites."
-- L["Your manual check-offs and skipped steps in the current guide are cleared. Quests you have done stay done."] = "Vos cases cochées et étapes passées dans le guide actuel sont effacées. Les quêtes faites restent faites."
-- L["How deep the night runs. Dusk is the default, Night the darkest, Graphite a neutral grey; EllesmereUI takes its panel colour and accent."] = "La profondeur de la nuit. Crépuscule par défaut, Nuit le plus sombre, Graphite un gris neutre ; EllesmereUI reprend sa couleur de panneau et son accent."
-- L["Appearance"] = "Apparence"
-- L["Points to the current goal. Its look and colours are under Appearance, Arrow."] = "Pointe vers l'objectif en cours. Son aspect et ses couleurs sont dans Apparence, Flèche."
-- L["Colour & type"] = "Couleurs et police"
-- L["Colours, type, window frames and the arrow. Everything repaints as you change it; right-click a setting to reset it."] = "Couleurs, police, cadres des fenêtres et flèche. Tout se met à jour en direct ; clic droit sur un réglage pour le réinitialiser."
-- L["Type & motion"] = "Police et animations"
-- L["Frame"] = "Cadre"
-- L["The whole guide window, text included. The background's own opacity is under Colour & type."] = "Toute la fenêtre du guide, texte compris. L'opacité du fond seul est dans Couleurs et police."
-- L["Map icons"] = "Icônes de carte"
-- L["Polestar's marks on the minimap; the world map keeps its own. A mark over your arrow fades so the arrow shows through it. Right-click to reset."] = "Les marques de Polestar sur la minicarte ; la carte du monde garde les siennes. Une marque sur votre flèche s'estompe pour laisser voir la flèche. Clic droit pour réinitialiser."
-- L["Sparkle"] = "Étincelles"
-- L["Subtle"] = "Discret"
-- L["Dazzling"] = "Éblouissant"
-- L["Route line style"] = "Style de ligne d'itinéraire"
-- L["Route colours tint each leg by how you travel it. Cyan, magenta and white stand apart from the minimap's yellow herb and ore dots and its gold quest marks. Right-click to reset."] = "Les couleurs d'itinéraire teintent chaque tronçon selon votre moyen de déplacement. Cyan, magenta et blanc se distinguent des points jaunes d'herbes et de minerais de la minicarte et de ses marques de quête dorées. Clic droit pour réinitialiser."
-- L["How thick the solid line is on the world map; the minimap's follows its size. Right-click to reset."] = "L'épaisseur de la ligne continue sur la carte du monde ; celle de la minicarte suit sa taille. Clic droit pour réinitialiser."
-- L["Reset to default"] = "Rétablir par défaut"
-- L["Button size"] = "Taille des boutons"
-- L["Target name position"] = "Position du nom de la cible"
-- L["Scale of the quest item, Hearthstone, target and rare buttons. Drag one to move them all."] = "Échelle des boutons d'objet de quête, de pierre de foyer, de ciblage et de rare. Faites-en glisser un pour tous les déplacer."
-- L["Accent colour"] = "Couleur d'accent"
-- L["Background opacity"] = "Opacité du fond"
-- L["Border thickness"] = "Épaisseur de bordure"
-- L["Window scale"] = "Échelle de la fenêtre"
