-- L["The arrow as it closes on the target, and the ring when you arrive. Right-click to go back to jade."] = "La flèche à l'approche de la cible, et l'anneau à l'arrivée. Clic droit pour revenir au jade."
-- L["Class quest chime"] = "Carillon des quêtes de classe"
-- L["A short chime the first time a class quest chain's card shows. Off while the game's sound effects are off."] = "Un bref carillon la première fois que la carte d'une chaîne de quêtes de classe s'affiche. Muet tant que les effets sonores du jeu sont coupés."
-- L["Minimap icon size"] = "Taille des icônes de la minicarte"
-- L["Button in the game menu"] = "Bouton dans le menu du jeu"
-- L["Keep the bar shown"] = "Garder la barre affichée"
-- L["How bright each sparkle and its glow are."] = "L'éclat de chaque étincelle et de son halo."
-- L["How close together the sparkles sit, the same at any zoom."] = "L'espacement des étincelles, le même à tout niveau de zoom."
-- L["Flow toward goal"] = "Flux vers l'objectif"
-- L["Most sparkles shown"] = "Étincelles au maximum"
-- L["Line thickness"] = "Épaisseur de la ligne"
-- L["How strongly the route shows on the minimap, line, dots or sparkles; the world map keeps its own. Right-click to reset."] = "La visibilité de l'itinéraire sur la minicarte, ligne, points ou étincelles ; la carte du monde garde la sienne. Clic droit pour réinitialiser."
-- L["The route's line, dots or sparkles on the minimap, each style its own size; the world map keeps its own. Right-click to reset."] = "La ligne, les points ou les étincelles de l'itinéraire sur la minicarte, chaque style avec sa propre taille ; la carte du monde garde la sienne. Clic droit pour réinitialiser."
