-- L["Comparison"] = "Comparaison"
-- L["Rares & travel"] = "Rares et voyages"
-- L["Instance limits"] = "Limites d'instances"
-- L["The XP tracker is off (Options > Quality of Life > Trackers)."] = "Le suivi d'XP est désactivé (Options > Confort de jeu > Suivis)."
-- L["Learn new spells"] = "Apprendre les nouveaux sorts"
-- L["Learns every spell a class trainer offers that you can afford, and prints the total. Profession trainers are left alone. Hold Shift to skip."] = "Apprend chaque sort proposé par un maître de classe que vous pouvez payer, et affiche le total. Les maîtres de métier ne sont pas concernés. Maintenez Maj pour passer."
-- L["Loot and merchants"] = "Butin et marchands"
-- L["Dungeons are turned off (Options > Discovery > Dungeons)."] = "Les donjons sont désactivés (Options > Découverte > Donjons)."
-- L["The Dungeons section is turned off. Turn it on under Options > Discovery > Dungeons."] = "La section Donjons est désactivée. Activez-la dans Options > Découverte > Donjons."
-- L["History"] = "Historique"
-- L["Polestar's own look (the default), Halo (no frame, a soft dark veil, Fira Sans), Hearth (warm game colours), or the game's own art: WoW Forever, Blizzard and Classic. Style, compact mode and the colours you pick work in each."] = "L'apparence de Polestar (par défaut), Halo (sans cadre, un voile sombre aux bords adoucis, Fira Sans), Foyer (les couleurs chaudes du jeu), ou les graphismes du jeu : WoW Forever, Blizzard et Classique. Le style, le mode compact et les couleurs que vous choisissez s'appliquent à chacun."
-- L["Tirisfal Glades"] = "Clairières de Tirisfal"
-- L["Garren's Haunt"] = "Repaire de Garren"
-- L["Collect Doom Weed"] = "Ramasser Herbe funeste"
-- L["381 yd"] = "381 m"
-- L["Dungeons and battlegrounds"] = "Donjons et champs de bataille"
-- L["How near its spawn area must be for a suggestion to show. It goes again a little further out."] = "À quelle distance sa zone d'apparition doit se trouver pour qu'une suggestion s'affiche. Elle disparaît un peu plus loin."
-- L["When %s comes into sight, a card says so and the rare button targets him and waves. At most once every half hour, never in combat or instances."] = "Quand %s arrive en vue, une carte le signale et le bouton de rare le cible et le salue. Au plus une fois par demi-heure, jamais en combat ni en instance."
-- L["Characters is turned off. Turn it on under Options > Discovery > Characters."] = "Personnages est désactivé. Activez-le dans Options > Découverte > Personnages."
-- L["Dungeon heads-ups are off. Turn them back on under Options > Discovery > Dungeons."] = "Les alertes de donjon sont désactivées. Réactivez-les dans Options > Découverte > Donjons."
-- L["Colour & type"] = "Couleurs et police"
-- L["Manual check-offs and skips, current guide."] = "Coches manuelles et étapes passées, guide actuel."
-- L["Show window"] = "Afficher la fenêtre"
-- L["Taking %s closes %s for good."] = "Prendre %s ferme %s pour de bon."
